import React, { useState } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import { Sparkles, Loader2, Send } from 'lucide-react';
import { Button } from './ui/Button';

export const MediaAssistant: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);

  const generateIdeas = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setResult(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Generate 3 catchy advertising slogans and a brief display strategy for a digital signage screen about: ${prompt}. Format as bullet points.`,
        config: {
          temperature: 0.7,
          maxOutputTokens: 500,
        }
      });
      setResult(response.text || 'No response generated.');
    } catch (error) {
      console.error('Gemini error:', error);
      setResult('Failed to generate ideas. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-gradient-to-br from-indigo-900/20 to-slate-900 border border-indigo-500/30 rounded-2xl p-6 shadow-xl overflow-hidden relative">
      <div className="flex items-center gap-3 mb-4">
        <div className="p-2 bg-indigo-500/20 rounded-lg">
          <Sparkles className="text-indigo-400" size={20} />
        </div>
        <div>
          <h3 className="text-lg font-semibold text-white">AI Content Assistant</h3>
          <p className="text-sm text-slate-400">Stuck on ad copy? Let AI help you write.</p>
        </div>
      </div>

      <div className="flex gap-2 mb-6">
        <input
          type="text"
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="e.g., Seasonal coffee discounts, Gym membership sale..."
          className="flex-1 bg-slate-950 border border-slate-800 rounded-lg px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
        />
        <Button 
          onClick={generateIdeas} 
          disabled={loading || !prompt}
          icon={loading ? <Loader2 className="animate-spin" size={18} /> : <Send size={18} />}
        >
          {loading ? 'Thinking...' : 'Generate'}
        </Button>
      </div>

      {result && (
        <div className="bg-slate-950/50 rounded-xl p-4 border border-slate-800 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="prose prose-invert prose-sm max-w-none">
             {result.split('\n').map((line, i) => (
               <p key={i} className="mb-2 text-slate-300">{line}</p>
             ))}
          </div>
        </div>
      )}
    </div>
  );
};

