import React, { useState, useEffect, useRef } from 'react';
import { AppState, MediaItem } from '../types';
import { loadState, updateScreenHeartbeat } from '../services/storage';
import { Loader2, AlertCircle, RefreshCw, Monitor } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchData = () => {
    const freshState = loadState();
    setState(freshState);
    updateScreenHeartbeat(screenId);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 30000); // Pulse heartbeat every 30s

    // Sync when storage changes (from Admin tab)
    const handleStorage = () => fetchData();
    window.addEventListener('storage_update', handleStorage);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage_update', handleStorage);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium">Inicializando Player...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <div className="space-y-2">
          <h2 className="text-3xl font-bold text-white">Tela não encontrada</h2>
          <p className="text-lg text-slate-500 max-w-md">O ID da tela "{screenId}" não está registrado. Verifique a URL ou registre o dispositivo no painel.</p>
        </div>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white hover:bg-slate-700 transition-colors flex items-center gap-2">
          <RefreshCw size={20} /> Tentar novamente
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500">
        <Monitor size={80} className="mb-6 opacity-20" />
        <h2 className="text-2xl font-semibold">Nenhum conteúdo agendado</h2>
        <p>Atribua uma playlist para "{screen.name}" para iniciar a transmissão.</p>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  return (
    <div className="h-screen w-screen bg-black overflow-hidden relative select-none">
      {/* Media Rendering */}
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000"
            key={activeItem.id}
          />
        ) : (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            loop={false}
            className="w-full h-full object-cover"
            onEnded={() => setCurrentIndex((prev) => (prev + 1) % currentItems.length)}
          />
        )}
      </div>

      {/* Marca d'água opcional */}
      <div className="absolute bottom-10 left-10 flex items-center gap-3 bg-black/40 backdrop-blur-md border border-white/10 px-4 py-2 rounded-full opacity-60 hover:opacity-100 transition-opacity">
        <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse" />
        <span className="text-white text-sm font-semibold tracking-wide">{screen.name}</span>
      </div>

      {/* Barra de progresso da transição */}
      <div className="absolute bottom-0 left-0 h-1.5 bg-indigo-600/50 w-full overflow-hidden">
        <div 
          className="h-full bg-indigo-500 transition-all ease-linear"
          style={{ 
            width: '100%',
            animation: `progress ${(activeItem.duration || 10)}s linear infinite` 
          }}
          key={currentIndex}
        />
      </div>

      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
      `}</style>
    </div>
  );
};

