import React, { useState } from 'react';
import { AppState, Screen } from '../types';
import { Button } from './ui/Button';
import { 
  Plus, 
  ExternalLink, 
  Wifi, 
  WifiOff, 
  Settings2, 
  Trash2, 
  X, 
  Tv, 
  Monitor,
  Check
} from 'lucide-react';
