}

import { AppState, Screen, Playlist, MediaItem } from '../types';
import { INITIAL_MEDIA, INITIAL_PLAYLISTS, INITIAL_SCREENS } from '../constants';

const STORAGE_KEY = 'adcast_state';

// Simulador de Nuvem usando JSONBin.io (chave pública para demonstração)
// Em produção, isso seria um backend real com autenticação.
const CLOUD_API_BASE = 'https://api.jsonbin.io/v3/b';
const MASTER_KEY = '$2a$10$7Z/2Zq6.v8O5/G.6Yh6iA.7/e/9v5yY8E6Iq9Y'; // Exemplo meramente ilustrativo

export const saveState = async (state: AppState) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  window.dispatchEvent(new Event('storage_update'));

  // Se houver um ID de sincronização, tentamos salvar na "nuvem"
  if (state.syncId) {
    try {
      // Nota: No mundo real, aqui faríamos um POST/PUT para um backend persistente
      // Para este protótipo, mantemos o local como fonte da verdade e simulamos a persistência
      console.log('Sincronizando com a nuvem ID:', state.syncId);
    } catch (e) {
      console.error('Erro na sincronização remota:', e);
    }
  }
};

export const loadState = (): AppState => {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (!stored) {
    const defaultState: AppState = {
      screens: INITIAL_SCREENS,
      playlists: INITIAL_PLAYLISTS,
      library: INITIAL_MEDIA,
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(defaultState));
    return defaultState;
  }
  return JSON.parse(stored);
};

export const updateScreenHeartbeat = (screenId: string) => {
  const state = loadState();
  const screen = state.screens.find(s => s.id === screenId);
  if (screen) {
    screen.status = 'online';
    screen.lastSeen = Date.now();
    saveState(state);
  }
};

