import React, { useState, useEffect } from 'react';
import { ViewType, AppState } from './types';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ScreenManager } from './components/ScreenManager';
import { PlaylistManager } from './components/PlaylistManager';
import { MediaLibrary } from './components/MediaLibrary';
import { Player } from './components/Player';
import { loadState, saveState } from './services/storage';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [playerScreenId, setPlayerScreenId] = useState<string | null>(null);
  const [state, setState] = useState<AppState>(loadState());

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash.startsWith('#player/')) {
        const id = hash.replace('#player/', '');
        setPlayerScreenId(id);
        setCurrentView('player');
      } else {
        setPlayerScreenId(null);
        // Map common hashes to views
        if (hash === '#screens') setCurrentView('screens');
        else if (hash === '#playlists') setCurrentView('playlists');
        else if (hash === '#library') setCurrentView('library');
        else setCurrentView('dashboard');
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange(); // Initial check

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const updateState = (newState: AppState) => {
    setState(newState);
    saveState(newState);
  };

  // Dedicated Player View
  if (currentView === 'player' && playerScreenId) {
    return <Player screenId={playerScreenId} />;
  }

  // Admin Views
  const renderView = () => {
    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={state} onUpdate={updateState} />;
      case 'screens':
        return <ScreenManager state={state} onUpdate={updateState} />;
      case 'playlists':
        return <PlaylistManager state={state} onUpdate={updateState} />;
      case 'library':
        return <MediaLibrary state={state} onUpdate={updateState} />;
      default:
        return <Dashboard state={state} onUpdate={updateState} />;
    }
  };

  return (
    <Layout currentView={currentView} onViewChange={(v) => {
      window.location.hash = v;
      setCurrentView(v);
    }}>
      {renderView()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, MediaItem } from '../types';
import { loadState, updateScreenHeartbeat } from '../services/storage';
import { Loader2, AlertCircle, RefreshCw, Monitor, Cloud } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchData = () => {
    // Para esta versão, usamos o localStorage como ponte. 
    // Em um sistema real, aqui buscaríamos do SyncId da URL se presente.
    const freshState = loadState();
    setState(freshState);
    updateScreenHeartbeat(screenId);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 30000); // Pulse heartbeat every 30s

    // Sync when storage changes (from Admin tab in the same browser)
    const handleStorage = () => fetchData();
    window.addEventListener('storage_update', handleStorage);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage_update', handleStorage);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium">Conectando ao AdCast Cloud...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <div className="space-y-2">
          <h2 className="text-3xl font-bold text-white">Tela não vinculada</h2>
          <p className="text-lg text-slate-500 max-w-md">O ID "{screenId}" não existe neste projeto.</p>
        </div>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white hover:bg-slate-700 transition-colors flex items-center gap-2">
          <RefreshCw size={20} /> Reconectar
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500">
