import React, { useState, useEffect, useRef } from 'react';
import { AppState, MediaItem } from '../types';
import { loadState, updateScreenHeartbeat, loadRemoteState } from '../services/storage';
import { Loader2, AlertCircle, RefreshCw, Monitor, Cloud, Wifi } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isRemote, setIsRemote] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchData = async () => {
    // Tenta pegar o syncId da URL: ?sync=prj-xyz
    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    if (syncId) {
      const remoteState = await loadRemoteState(syncId);
      if (remoteState) {
        setState(remoteState);
        setIsRemote(true);
      }
    } else {
      // Fallback para local se estiver no mesmo navegador
      setState(loadState());
    }

    updateScreenHeartbeat(screenId, syncId || undefined);
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    // Polling a cada 20 segundos para checar novas playlists no Supabase
    const interval = setInterval(fetchData, 20000); 

    const handleStorage = () => fetchData();
    window.addEventListener('storage_update', handleStorage);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage_update', handleStorage);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium">Sincronizando com Supabase Cloud...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <div className="space-y-2">
          <h2 className="text-3xl font-bold text-white">Tela não vinculada</h2>
          <p className="text-lg text-slate-500 max-w-md">O ID "{screenId}" não foi encontrado neste projeto remoto.</p>
        </div>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white hover:bg-slate-700 transition-colors flex items-center gap-2">
          <RefreshCw size={20} /> Tentar Novamente
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500">
        <Monitor size={80} className="mb-6 opacity-20" />
        <h2 className="text-2xl font-semibold">Aguardando Programação</h2>
        <p className="mb-4 text-slate-400">ID da Tela: <span className="text-white font-mono">{screenId}</span></p>
        <div className="flex items-center gap-2 px-3 py-1 bg-slate-950 rounded-full border border-slate-800 text-[10px] uppercase font-bold tracking-widest text-emerald-500">
          <Wifi size={10} /> {isRemote ? 'Supabase Online' : 'Local Mode'}
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  return (
    <div className="h-screen w-screen bg-black overflow-hidden relative select-none">
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000"
            key={activeItem.id}
          />
        ) : (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={() => setCurrentIndex((prev) => (prev + 1) % currentItems.length)}
          />
        )}
      </div>

      <div className="absolute bottom-10 left-10 flex flex-col gap-1 z-50">
        <div className="flex items-center gap-3 bg-black/40 backdrop-blur-md border border-white/10 px-4 py-2 rounded-full opacity-60">
          <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse" />
          <span className="text-white text-xs font-semibold">{screen.name}</span>
        </div>
      </div>

      <div className="absolute bottom-0 left-0 h-1 bg-indigo-600/20 w-full z-50">
        <div 
          className="h-full bg-indigo-500 transition-all ease-linear"
          style={{ 
            width: '100%',
            animation: `progress ${(activeItem.duration || 10)}s linear infinite` 
          }}
          key={`${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
      `}</style>
    </div>
  );
};

import React, { useState } from 'react';
import { AppState, Screen } from '../types';
import { Button } from './ui/Button';
import { 
  Plus, 
  ExternalLink, 
  Wifi, 
  WifiOff, 
  Settings2, 
  Trash2, 
  X, 
  Tv, 
  Monitor,
  Check,
  Copy,
  Link as LinkIcon
} from 'lucide-react';

interface ScreenManagerProps {
  state: AppState;
  onUpdate: (newState: AppState) => void;
}

export const ScreenManager: React.FC<ScreenManagerProps> = ({ state, onUpdate }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [newScreenName, setNewScreenName] = useState('');

  const handleAddScreen = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newScreenName.trim()) return;

    const newScreen: Screen = {
      id: `scr-${Math.random().toString(36).substr(2, 9)}`,
      name: newScreenName,
      status: 'offline',
      lastSeen: Date.now(),
      currentPlaylistId: null,
    };

    const newState = {
      ...state,
      screens: [...state.screens, newScreen]
    };

    onUpdate(newState);
    setNewScreenName('');
    setShowAddForm(false);
  };

  const handleDeleteScreen = (id: string) => {
    if (confirm('Tem certeza que deseja remover esta tela? O link do player deixará de funcionar.')) {
      const newState = {
        ...state,
        screens: state.screens.filter(s => s.id !== id)
      };
      onUpdate(newState);
    }
  };

  const togglePlaylist = (screenId: string, playlistId: string) => {
    const newState = {
      ...state,
      screens: state.screens.map(s => 
        s.id === screenId ? { ...s, currentPlaylistId: playlistId || null } : s
      )
    };
    onUpdate(newState);
  };

  const getPlayerUrl = (screenId: string) => {
    const baseUrl = `${window.location.origin}${window.location.pathname}`;
    const syncParam = state.syncId ? `?sync=${state.syncId}` : '';
    return `${baseUrl}${syncParam}#player/${screenId}`;
  };

  const openPlayer = (screenId: string) => {
    window.open(getPlayerUrl(screenId), '_blank');
  };

  const copyPlayerUrl = (screenId: string) => {
    navigator.clipboard.writeText(getPlayerUrl(screenId));
    alert('URL do Player copiada! Cole no navegador da sua Smart TV.');
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h3 className="text-2xl font-bold text-white">Suas Telas</h3>
          <p className="text-slate-400">Gerencie seus dispositivos conectados e links de transmissão.</p>
        </div>
        <Button 
          icon={showAddForm ? <X size={18} /> : <Plus size={18} />} 
          variant={showAddForm ? 'secondary' : 'primary'}
          onClick={() => setShowAddForm(!showAddForm)}
        >
          {showAddForm ? 'Cancelar' : 'Registrar Nova Tela'}
        </Button>
      </div>

      {showAddForm && (
        <div className="bg-slate-900 border border-indigo-500/30 p-6 rounded-2xl animate-in fade-in slide-in-from-top-4 duration-300 shadow-2xl">
          <form onSubmit={handleAddScreen} className="flex flex-col md:flex-row items-end gap-4">
            <div className="flex-1 space-y-2 w-full">
              <label className="text-xs font-semibold text-slate-400 uppercase tracking-wider flex items-center gap-2">
                <Tv size={14} /> Nome da Nova Tela
              </label>
              <input 
                type="text" 
                autoFocus
                required
                value={newScreenName}
                onChange={e => setNewScreenName(e.target.value)}
                placeholder="Ex: Monitor Corredor B, TV Lounge..."
                className="w-full bg-slate-950 border border-slate-800 rounded-lg px-4 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none transition-all"
              />
            </div>
            <Button type="submit" className="w-full md:w-auto" icon={<Check size={18} />}>
              Salvar Dispositivo
            </Button>
          </form>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {state.screens.map((screen) => (
          <div key={screen.id} className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden group hover:border-indigo-500/50 transition-all duration-300 shadow-lg">
            <div className="p-6">
              <div className="flex justify-between items-start mb-4">
                <div className={`p-3 rounded-xl bg-slate-950 border border-slate-800/50 ${screen.status === 'online' ? 'text-emerald-500 shadow-[0_0_15px_rgba(16,185,129,0.1)]' : 'text-slate-600'}`}>
                  {screen.status === 'online' ? <Wifi size={24} /> : <WifiOff size={24} />}
                </div>
                <div className="flex gap-1">
                  <button 
                    onClick={() => copyPlayerUrl(screen.id)}
                    className="p-2 hover:bg-indigo-500/10 rounded-lg text-slate-500 hover:text-indigo-400 transition-colors"
                    title="Copiar URL do Player"
                  >
                    <LinkIcon size={18} />
                  </button>
                  <button 
                    onClick={() => handleDeleteScreen(screen.id)}
                    className="p-2 hover:bg-rose-500/10 rounded-lg text-slate-500 hover:text-rose-500 transition-colors"
                    title="Excluir tela"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              <div className="mb-6">
                <h4 className="text-lg font-bold text-white group-hover:text-indigo-400 transition-colors truncate" title={screen.name}>
                  {screen.name}
                </h4>
                <div className="flex items-center gap-2 text-xs text-slate-500">
                  <span className="font-mono bg-slate-950 px-1.5 py-0.5 rounded border border-slate-800">{screen.id}</span>
                  <span>•</span>
                  <span>{screen.status === 'online' ? 'Conectado' : 'Offline'}</span>
                </div>
              </div>

              <div className="space-y-4">
                <div>
                  <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider block mb-2">Playlist Ativa</label>
                  <select 
                    value={screen.currentPlaylistId || ''} 
                    onChange={(e) => togglePlaylist(screen.id, e.target.value)}
                    className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-sm focus:ring-1 focus:ring-indigo-500 outline-none text-white cursor-pointer hover:border-slate-700 transition-colors"
                  >
                    <option value="">Nenhuma agendada</option>
                    {state.playlists.map(p => (
                      <option key={p.id} value={p.id}>{p.name}</option>
                    ))}
                  </select>
                </div>

                <div className="flex gap-2">
                  <Button 
                    variant="secondary" 
                    size="sm" 
                    className="flex-1 bg-slate-950 border-slate-800" 
                    icon={<ExternalLink size={16} />}
                    onClick={() => openPlayer(screen.id)}
                  >
                    Testar Player
                  </Button>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

