    return data.state as AppState;
  } catch (e) {
    return null;
  }
};

// Heartbeat otimizado: Atualiza apenas o status da tela em uma tabela dedicada
// Evita que o Player sobrescreva as configurações do projeto no Supabase
export const updateScreenHeartbeat = async (screenId: string, syncId?: string) => {
  if (!syncId) return;

  try {
    await supabase
      .from('screen_status')
      .upsert({ 
        screen_id: screenId, 
        project_id: syncId, 
        last_seen: new Date().toISOString()
      });
  } catch (e) {
    console.warn('⚠️ Falha ao enviar heartbeat:', e);
  }
};

// Busca status em tempo real de todas as telas de um projeto
export const getLiveScreensStatus = async (syncId: string) => {
  try {
    const { data, error } = await supabase
      .from('screen_status')
      .select('screen_id, last_seen')
      .eq('project_id', syncId);

    if (error) throw error;
    return data;
  } catch (e) {
    return [];
  }
};

import React, { useEffect, useState } from 'react';
import { AppState } from '../types';
import { 
  Monitor, 
  PlaySquare, 
  Library, 
  Activity,
  ArrowUpRight,
  Plus,
  RefreshCw
} from 'lucide-react';
import { Button } from './ui/Button';
import { MediaAssistant } from './MediaAssistant';
import { SyncManager } from './SyncManager';
import { getLiveScreensStatus } from '../services/storage';

interface DashboardProps {
  state: AppState;
  onUpdate: (newState: AppState) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ state, onUpdate }) => {
  const [liveStatus, setLiveStatus] = useState<Record<string, number>>({});
  const [refreshing, setRefreshing] = useState(false);

  const refreshLiveStatus = async () => {
    if (!state.syncId) return;
    setRefreshing(true);
    const statuses = await getLiveScreensStatus(state.syncId);
    const statusMap: Record<string, number> = {};
    statuses.forEach((s: any) => {
      statusMap[s.screen_id] = new Date(s.last_seen).getTime();
    });
    setLiveStatus(statusMap);
    setRefreshing(false);
  };

  useEffect(() => {
    refreshLiveStatus();
    const interval = setInterval(refreshLiveStatus, 15000);
    return () => clearInterval(interval);
  }, [state.syncId]);

  const isOnline = (screenId: string) => {
    const lastSeen = liveStatus[screenId];
    if (!lastSeen) return false;
    // Considera online se o último sinal foi há menos de 1 minuto
    return (Date.now() - lastSeen) < 60000;
  };

  const stats = [
    { label: 'Telas Online', value: state.screens.filter(s => isOnline(s.id)).length, total: state.screens.length, icon: <Monitor className="text-emerald-400" />, bg: 'bg-emerald-400/10' },
    { label: 'Playlists Ativas', value: state.playlists.length, icon: <PlaySquare className="text-indigo-400" />, bg: 'bg-indigo-400/10' },
    { label: 'Biblioteca', value: state.library.length, icon: <Library className="text-amber-400" />, bg: 'bg-amber-400/10' },
    { label: 'Sincronização', value: state.syncId ? 'Nuvem' : 'Local', icon: <Activity className="text-blue-400" />, bg: 'bg-blue-400/10' },
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Estatísticas Rápidas */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, i) => (
          <div key={i} className="bg-slate-900 border border-slate-800 p-6 rounded-2xl flex flex-col gap-4 shadow-lg hover:border-slate-700 transition-colors">
            <div className="flex justify-between items-start">
              <div className={`p-3 ${stat.bg} rounded-xl`}>
                {stat.icon}
              </div>
              <ArrowUpRight size={18} className="text-slate-600" />
            </div>
            <div>
              <p className="text-slate-400 text-xs font-bold uppercase tracking-wider">{stat.label}</p>
              <div className="flex items-baseline gap-2">
                <h4 className="text-2xl font-bold text-white">{stat.value}</h4>
                {stat.total !== undefined && <span className="text-slate-500 text-sm font-medium">/ {stat.total}</span>}
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          <SyncManager state={state} onUpdate={onUpdate} />

          <MediaAssistant />

          <div className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden shadow-xl">
            <div className="p-6 border-b border-slate-800 flex justify-between items-center bg-slate-900/50">
              <div className="flex items-center gap-2">
                <h3 className="font-bold text-white">Status das Telas (Real-time)</h3>
                {refreshing && <RefreshCw size={14} className="animate-spin text-indigo-400" />}
              </div>
              <Button variant="ghost" size="sm" onClick={refreshLiveStatus}>Atualizar</Button>
            </div>
            <div className="divide-y divide-slate-800">
              {state.screens.map(screen => {
                const online = isOnline(screen.id);
                return (
                  <div key={screen.id} className="p-4 flex items-center justify-between hover:bg-slate-800/30 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className={`w-3 h-3 rounded-full ${online ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.4)]' : 'bg-slate-700'}`} />
                      <div>
                        <p className="font-semibold text-slate-200">{screen.name}</p>
                        <p className="text-[10px] font-mono text-slate-500 uppercase tracking-tighter">ID: {screen.id}</p>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className={`text-xs font-bold ${online ? 'text-emerald-400' : 'text-slate-500'}`}>
                        {online ? 'ONLINE' : 'DESCONECTADA'}
                      </p>
                      <p className="text-[10px] text-slate-600">
                        {liveStatus[screen.id] ? new Date(liveStatus[screen.id]).toLocaleTimeString() : 'Nunca vista'}
                      </p>
                    </div>
                  </div>
                );
              })}
              {state.screens.length === 0 && (
                <div className="p-10 text-center text-slate-500 italic text-sm">Nenhuma tela cadastrada para monitoramento.</div>
              )}
            </div>
          </div>
        </div>

        <div className="space-y-8">
          <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl">
            <div className="flex justify-between items-center mb-6">
              <h3 className="font-bold text-white">Biblioteca de Mídia</h3>
              <Button variant="ghost" size="sm" icon={<Plus size={16} />}>Novo</Button>
