          </div>

          <div className="bg-gradient-to-br from-indigo-600 to-blue-700 rounded-2xl p-6 text-white shadow-2xl relative overflow-hidden group">
            <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform">
              <Monitor size={120} />
            </div>
            <h4 className="font-black text-xl mb-2 relative z-10 italic uppercase tracking-tight">Pronto para escalar?</h4>
            <p className="text-indigo-100 text-sm mb-6 relative z-10 leading-relaxed">Conecte TVs ilimitadas e gerencie tudo em tempo real através da nuvem Supabase.</p>
            <Button className="w-full bg-white text-indigo-600 border-none hover:bg-slate-100 font-bold shadow-xl">Ver Documentação</Button>
          </div>
        </div>
      </div>
    </div>
  );
