import React, { useState, useEffect, useRef } from 'react';
import { AppState, MediaItem } from '../types';
import { loadState, updateScreenHeartbeat, loadRemoteState } from '../services/storage';
import { Loader2, AlertCircle, RefreshCw, Monitor, Cloud, Wifi } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isRemote, setIsRemote] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchData = async () => {
    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    if (syncId) {
      const remoteState = await loadRemoteState(syncId);
      if (remoteState) {
        setState(remoteState);
        setIsRemote(true);
      }
      // Envia heartbeat para a tabela dedicada
      updateScreenHeartbeat(screenId, syncId);
    } else {
      const localState = loadState();
      setState(localState);
      updateScreenHeartbeat(screenId, localState.syncId);
    }

    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 30000); // Polling a cada 30s

    const handleStorage = () => fetchData();
    window.addEventListener('storage_update', handleStorage);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage_update', handleStorage);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight">Sincronizando AdCast Cloud...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <div className="space-y-2">
          <h2 className="text-3xl font-bold text-white">Terminal não Autorizado</h2>
          <p className="text-lg text-slate-500 max-w-md">O ID <span className="text-rose-400 font-mono">{screenId}</span> não existe neste projeto.</p>
        </div>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white hover:bg-slate-700 transition-colors flex items-center gap-2 font-bold">
          <RefreshCw size={20} /> Reconectar
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center">
        <Monitor size={100} className="mb-8 opacity-10 animate-pulse" />
        <h2 className="text-3xl font-black text-white uppercase tracking-tighter mb-2">Aguardando Playlist</h2>
        <p className="mb-8 text-slate-400 text-lg">Este terminal está configurado como <span className="text-indigo-400 font-bold">{screen.name}</span></p>
        <div className="flex items-center gap-2 px-4 py-2 bg-slate-950 rounded-full border border-slate-800 text-xs uppercase font-black tracking-widest text-emerald-500 shadow-xl">
          <Wifi size={14} /> Conectado via {isRemote ? 'Supabase' : 'Cache Local'}
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  return (
    <div className="h-screen w-screen bg-black overflow-hidden relative select-none">
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000"
            key={activeItem.id}
          />
        ) : (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={() => setCurrentIndex((prev) => (prev + 1) % currentItems.length)}
          />
        )}
      </div>

      {/* Overlay de Status (Sutil) */}
      <div className="absolute bottom-8 left-8 z-50 flex items-center gap-3 bg-black/30 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full opacity-0 hover:opacity-100 transition-opacity duration-500">
        <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.8)]" />
        <span className="text-white text-xs font-black uppercase tracking-widest">{screen.name}</span>
      </div>

      {/* Progress Bar */}
      <div className="absolute bottom-0 left-0 h-1.5 bg-white/5 w-full z-50">
        <div 
          className="h-full bg-indigo-500 shadow-[0_0_15px_rgba(99,102,241,0.8)]"
          style={{ 
            width: '100%',
            animation: `progress ${(activeItem.duration || 10)}s linear infinite` 
          }}
          key={`${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
      `}</style>
    </div>
  );
};

import { AppState } from '../types';
import { INITIAL_MEDIA, INITIAL_PLAYLISTS, INITIAL_SCREENS } from '../constants';
import { supabase } from './supabase';

const STORAGE_KEY = 'adcast_state';

// Salva o estado do projeto (Configurações, Playlists, Mídias)
export const saveState = async (state: AppState) => {
  // Salva no cache local do Administrador
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  window.dispatchEvent(new Event('storage_update'));

  if (state.syncId) {
    try {
      const { error } = await supabase
        .from('adcast_projects')
        .upsert({ 
          id: state.syncId, 
          state: state,
          updated_at: new Date().toISOString()
        }, { onConflict: 'id' });

      if (error) throw error;
    } catch (e) {
      console.error('❌ Erro Supabase Sync:', e);
    }
  }
};

export const loadState = (): AppState => {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (!stored) {
    const defaultState: AppState = {
      screens: INITIAL_SCREENS,
      playlists: INITIAL_PLAYLISTS,
      library: INITIAL_MEDIA,
    };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(defaultState));
    return defaultState;
  }
  return JSON.parse(stored);
};

export const loadRemoteState = async (syncId: string): Promise<AppState | null> => {
  try {
    const { data, error } = await supabase
      .from('adcast_projects')
      .select('state')
      .eq('id', syncId)
      .single();

    if (error) throw error;
    return data.state as AppState;
  } catch (e) {
    return null;
  }
};

// Escuta mudanças no projeto em tempo real (Usado pelo Player)
export const subscribeToProject = (syncId: string, callback: (newState: AppState) => void) => {
  return supabase
    .channel(`project-${syncId}`)
    .on(
      'postgres_changes',
      {
        event: 'UPDATE',
        schema: 'public',
        table: 'adcast_projects',
        filter: `id=eq.${syncId}`,
      },
      (payload) => {
        callback(payload.new.state as AppState);
      }
    )
    .subscribe();
};

// Heartbeat otimizado
export const updateScreenHeartbeat = async (screenId: string, syncId?: string) => {
  if (!syncId) return;

  try {
    await supabase
      .from('screen_status')
      .upsert({ 
        screen_id: screenId, 
        project_id: syncId, 
        last_seen: new Date().toISOString()
      }, { onConflict: 'screen_id' });
  } catch (e) {
    console.warn('⚠️ Falha ao enviar heartbeat:', e);
  }
};

// Busca status em tempo real de todas as telas de um projeto
export const getLiveScreensStatus = async (syncId: string) => {
  try {
    const { data, error } = await supabase
      .from('screen_status')
      .select('screen_id, last_seen')
      .eq('project_id', syncId);

    if (error) throw error;
    return data;
  } catch (e) {
    return [];
  }
};

