import React, { useState } from 'react';
import { AppState } from '../types';
import { Button } from './ui/Button';
import { Cloud, CloudOff, Copy, Check, Globe, Database, ShieldCheck, AlertTriangle, Loader2 } from 'lucide-react';
import { checkSupabaseHealth } from '../services/storage';

interface SyncManagerProps {
  state: AppState;
  onUpdate: (newState: AppState) => void;
}

export const SyncManager: React.FC<SyncManagerProps> = ({ state, onUpdate }) => {
  const [copied, setCopied] = useState(false);
  const [healthStatus, setHealthStatus] = useState<{connected: boolean, tables: any, error?: string} | null>(null);
  const [checking, setChecking] = useState(false);

  const toggleSync = () => {
    if (state.syncId) {
      if (confirm('Desativar a nuvem removerá o acesso remoto. Continuar?')) {
        onUpdate({ ...state, syncId: undefined });
        setHealthStatus(null);
      }
    } else {
      const newSyncId = `prj-${Math.random().toString(36).substr(2, 9)}`;
      onUpdate({ ...state, syncId: newSyncId });
    }
  };

  const verifySetup = async () => {
    setChecking(true);
    const status = await checkSupabaseHealth();
    setHealthStatus(status);
    setChecking(false);
  };

  const copyToken = () => {
    if (!state.syncId) return;
    navigator.clipboard.writeText(state.syncId);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className={`p-2 rounded-lg ${state.syncId ? 'bg-indigo-500/20 text-indigo-400' : 'bg-slate-800 text-slate-500'}`}>
            {state.syncId ? <Database size={20} /> : <CloudOff size={20} />}
          </div>
          <div>
            <h3 className="font-bold text-white tracking-tight">Infraestrutura Supabase</h3>
            <p className="text-[10px] text-slate-500 uppercase font-black tracking-widest">
              {state.syncId ? 'Cloud Sync Ativo' : 'Armazenamento Local'}
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          {state.syncId && (
            <Button variant="secondary" size="sm" onClick={verifySetup} disabled={checking}>
              {checking ? <Loader2 size={16} className="animate-spin" /> : 'Validar Tabelas'}
            </Button>
          )}
          <Button 
            variant={state.syncId ? 'ghost' : 'primary'} 
            size="sm"
            onClick={toggleSync}
          >
            {state.syncId ? 'Desativar' : 'Habilitar Cloud'}
          </Button>
        </div>
      </div>

      {healthStatus && (
        <div className={`mb-6 p-4 rounded-xl border ${healthStatus.connected ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-rose-500/5 border-rose-500/20'} animate-in slide-in-from-top-2`}>
          <div className="flex items-center gap-2 mb-3">
            {healthStatus.connected ? <ShieldCheck className="text-emerald-500" size={18} /> : <AlertTriangle className="text-rose-500" size={18} />}
            <span className={`text-xs font-bold ${healthStatus.connected ? 'text-emerald-400' : 'text-rose-400'}`}>
              {healthStatus.connected ? 'Estrutura do Banco de Dados OK' : 'Falha na Estrutura'}
            </span>
          </div>
          <div className="grid grid-cols-2 gap-2">
            {Object.entries(healthStatus.tables).map(([table, ok]) => (
              <div key={table} className="flex items-center gap-2 text-[10px] text-slate-400 font-mono">
                <div className={`w-1.5 h-1.5 rounded-full ${ok ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                {table}
              </div>
            ))}
          </div>
          {healthStatus.error && <p className="mt-2 text-[10px] text-rose-500 font-medium italic">Erro: {healthStatus.error}</p>}
        </div>
      )}

      {state.syncId && (
        <div className="space-y-4 animate-in fade-in slide-in-from-top-2">
          <div className="p-4 bg-slate-950 rounded-xl border border-slate-800 flex flex-col gap-2">
            <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Sync Key (Token do Projeto)</label>
            <div className="flex gap-2">
              <input 
                type="text" 
                readOnly 
                value={state.syncId} 
                className="flex-1 bg-transparent border-none text-indigo-400 font-mono text-sm focus:ring-0 p-0"
              />
              <button onClick={copyToken} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors">
                {copied ? <Check size={16} className="text-emerald-500" /> : <Copy size={16} />}
              </button>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div className="p-3 bg-indigo-500/5 border border-indigo-500/10 rounded-xl">
              <div className="flex items-center gap-2 mb-1">
                <Globe size={14} className="text-indigo-400" />
                <span className="text-[10px] font-bold text-slate-300 uppercase">Acesso Global</span>
              </div>
              <p className="text-[11px] text-slate-500 leading-tight">As TVs podem estar em qualquer rede Wi-Fi e receberão as ordens deste painel em milissegundos.</p>
            </div>
            <div className="p-3 bg-slate-800/20 border border-slate-700/50 rounded-xl">
              <div className="flex items-center gap-2 mb-1">
                <Database size={14} className="text-slate-400" />
                <span className="text-[10px] font-bold text-slate-300 uppercase">Resiliência Offline</span>
              </div>
              <p className="text-[11px] text-slate-500 leading-tight">As telas continuam exibindo o conteúdo mesmo se a internet cair temporariamente.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

