    const [mediaRes, playlistRes, playlistItemsRes, screensRes] = await Promise.all([
      supabase.from('adcast_media').select('*').eq('project_id', syncId),
      supabase.from('adcast_playlists').select('*').eq('project_id', syncId),
      supabase.from('adcast_playlist_items').select('*'),
      supabase.from('adcast_screens').select('*').eq('project_id', syncId)
    ]);

    if (mediaRes.error || playlistRes.error || screensRes.error) throw new Error('Fetch failed');

    // Mapear Playlists com seus Itens ordenados
    const playlists: Playlist[] = playlistRes.data.map(p => {
      const items = playlistItemsRes.data
        ?.filter(pi => pi.playlist_id === p.id)
        .sort((a, b) => a.position - b.position)
        .map(pi => pi.media_id) || [];

