  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isRemote, setIsRemote] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchData = async () => {
    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    if (syncId) {
      const remoteState = await loadRemoteState(syncId);
      if (remoteState) {
        setState(remoteState);
        setIsRemote(true);
      }
      updateScreenHeartbeat(screenId, syncId);
    } else {
      const localState = loadState();
      setState(localState);
      updateScreenHeartbeat(screenId, localState.syncId);
    }

    setLoading(false);
  };

  useEffect(() => {
    fetchData();

    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    let subscription: any = null;
    if (syncId) {
      subscription = subscribeToProjectChanges(syncId, async () => {
        console.log('⚡ Relational update detected');
        const updated = await loadRemoteState(syncId);
        if (updated) setState(updated);
      });
    }

    const heartbeatInterval = setInterval(() => {
      updateScreenHeartbeat(screenId, syncId || state?.syncId);
    }, 30000);

    return () => {
      if (subscription) subscription.unsubscribe();
      clearInterval(heartbeatInterval);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight">Iniciando Terminal de Vídeo...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <h2 className="text-3xl font-bold text-white">Terminal não Registrado</h2>
        <p className="text-lg text-slate-500 max-w-md">ID: <span className="text-rose-400 font-mono">{screenId}</span></p>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white">
          Tentar Reconectar
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center">
        <Monitor size={100} className="mb-8 opacity-10" />
        <h2 className="text-3xl font-black text-white uppercase mb-2">Sem Programação</h2>
        <p className="mb-8 text-slate-400">{screen.name}</p>
        <div className="flex gap-4">
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-950 rounded-full border border-slate-800 text-xs text-emerald-500">
            <Wifi size={14} /> {isRemote ? 'Cloud Connected' : 'Local Only'}
          </div>
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  return (
    <div className="h-screen w-screen bg-black overflow-hidden relative select-none">
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000"
            key={activeItem.id}
          />
        ) : (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={() => setCurrentIndex((prev) => (prev + 1) % currentItems.length)}
          />
        )}
      </div>

      <div className="absolute bottom-8 left-8 z-50 flex items-center gap-3 bg-black/30 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full">
        <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.8)]" />
        <span className="text-white text-xs font-black uppercase tracking-widest">{screen.name}</span>
      </div>

      <div className="absolute bottom-0 left-0 h-1 bg-indigo-500/30 w-full z-50">
        <div 
          className="h-full bg-indigo-500"
          style={{ 
            width: '100%',
            animation: `progress ${(activeItem.duration || 10)}s linear infinite` 
          }}
          key={`${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
      `}</style>
    </div>
  );
};

