import React, { useState } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import { Sparkles, Loader2, Send } from 'lucide-react';
import { Button } from './ui/Button';

export const MediaAssistant: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);

  const generateIdeas = async () => {
    if (!prompt.trim()) return;
    setLoading(true);
    setResult(null);

    try {
      // Fix: Always create a new GoogleGenAI instance right before making an API call
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Gere 3 slogans publicitários cativantes e uma breve estratégia de exibição para uma tela de sinalização digital sobre: ${prompt}. Formate em tópicos e responda em Português do Brasil.`,
        config: {
          temperature: 0.7,
          // Fix: When using maxOutputTokens, thinkingConfig must be provided for Gemini 3 series models
          maxOutputTokens: 500,
          thinkingConfig: { thinkingBudget: 100 }
        }
      });
      // Fix: Directly access the .text property (not a method) as per guidelines
      setResult(response.text || 'Nenhuma resposta gerada.');
    } catch (error) {
      console.error('Erro Gemini:', error);
      setResult('Falha ao gerar ideias. Por favor, tente novamente.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-gradient-to-br from-indigo-900/20 to-slate-900 border border-indigo-500/30 rounded-2xl p-6 shadow-xl overflow-hidden relative">
      <div className="flex items-center gap-3 mb-4">
        <div className="p-2 bg-indigo-500/20 rounded-lg">
          <Sparkles className="text-indigo-400" size={20} />
        </div>
        <div>
          <h3 className="text-lg font-semibold text-white">Assistente de Conteúdo IA</h3>
          <p className="text-sm text-slate-400">Sem ideias para o anúncio? Deixe a IA ajudar você.</p>
        </div>
      </div>

      <div className="flex gap-2 mb-6">
        <input
          type="text"
          value={prompt}
          onChange={(e) => setPrompt(e.target.value)}
          placeholder="ex: Descontos sazonais de café, Venda de planos de academia..."
          className="flex-1 bg-slate-950 border border-slate-800 rounded-lg px-4 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-white"
        />
        <Button 
          onClick={generateIdeas} 
          disabled={loading || !prompt}
          icon={loading ? <Loader2 className="animate-spin" size={18} /> : <Send size={18} />}
        >
          {loading ? 'Pensando...' : 'Gerar'}
        </Button>
      </div>

      {result && (
        <div className="bg-slate-950/50 rounded-xl p-4 border border-slate-800 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="prose prose-invert prose-sm max-w-none">
             {result.split('\n').map((line, i) => (
               <p key={i} className="mb-2 text-slate-300">{line}</p>
             ))}
          </div>
        </div>
      )}
    </div>
  );
};

import { AppState, MediaItem, Playlist, Screen } from '../types';
import { INITIAL_MEDIA, INITIAL_PLAYLISTS, INITIAL_SCREENS } from '../constants';
import { supabase } from './supabase';

const STORAGE_KEY = 'adcast_state';

// Carrega o estado inicial (Fallback Local)
export const loadState = (): AppState => {
  const stored = localStorage.getItem(STORAGE_KEY);
  if (!stored) {
    return {
      screens: INITIAL_SCREENS,
      playlists: INITIAL_PLAYLISTS,
      library: INITIAL_MEDIA,
    };
  }
  return JSON.parse(stored);
};

// SALVAMENTO RELACIONAL COMPLETO
export const saveState = async (state: AppState) => {
  // 1. Persistência Local
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  window.dispatchEvent(new Event('storage_update'));

  // 2. Persistência Nuvem (Relacional)
  if (!state.syncId) return;

  try {
    const projectId = state.syncId;

    // A. Sincronizar Mídias
    if (state.library.length > 0) {
      await supabase.from('adcast_media').upsert(
        state.library.map(m => ({
          id: m.id,
          project_id: projectId,
          name: m.name,
          url: m.url,
          type: m.type,
          duration: m.duration
        }))
      );
    }

    // B. Sincronizar Playlists
    if (state.playlists.length > 0) {
      await supabase.from('adcast_playlists').upsert(
        state.playlists.map(p => ({
          id: p.id,
          project_id: projectId,
          name: p.name
        }))
      );

      // Sincronizar Itens das Playlists
      for (const playlist of state.playlists) {
        await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlist.id);
        if (playlist.items.length > 0) {
          await supabase.from('adcast_playlist_items').insert(
            playlist.items.map((mediaId, index) => ({
              playlist_id: playlist.id,
              media_id: mediaId,
              position: index
            }))
          );
        }
      }
    }

    // C. Sincronizar Telas
    if (state.screens.length > 0) {
      await supabase.from('adcast_screens').upsert(
        state.screens.map(s => ({
          id: s.id,
          project_id: projectId,
          name: s.name,
          current_playlist_id: s.currentPlaylistId
        }))
      );
    }

    console.log('✅ Cloud Synced: Relational Data structure updated.');
  } catch (e) {
    console.error('❌ Cloud Sync Error:', e);
  }
};

// CARREGAMENTO RELACIONAL COMPLETO
export const loadRemoteState = async (syncId: string): Promise<AppState | null> => {
  try {
    // Busca paralela para máxima performance
    const [mediaRes, playlistRes, screensRes] = await Promise.all([
      supabase.from('adcast_media').select('*').eq('project_id', syncId),
      supabase.from('adcast_playlists').select('*').eq('project_id', syncId),
      supabase.from('adcast_screens').select('*').eq('project_id', syncId)
    ]);

    if (mediaRes.error || playlistRes.error || screensRes.error) throw new Error('Fetch failed');

    // Busca itens das playlists apenas das playlists deste projeto (Segurança e Performance)
    const playlistIds = playlistRes.data.map(p => p.id);
    const playlistItemsRes = playlistIds.length > 0 
      ? await supabase.from('adcast_playlist_items').select('*').in('playlist_id', playlistIds)
      : { data: [], error: null };

    // Mapear Playlists com seus Itens ordenados
    const playlists: Playlist[] = playlistRes.data.map(p => {
      const items = playlistItemsRes.data
        ?.filter(pi => pi.playlist_id === p.id)
        .sort((a, b) => a.position - b.position)
        .map(pi => pi.media_id) || [];

      return { id: p.id, name: p.name, items };
    });

    return {
      syncId,
      library: mediaRes.data as MediaItem[],
      playlists: playlists,
      screens: screensRes.data.map(s => ({
        id: s.id,
        name: s.name,
        currentPlaylistId: s.current_playlist_id,
        status: s.status,
        lastSeen: new Date(s.last_seen).getTime()
      })) as Screen[]
    };
  } catch (e) {
    console.error('❌ Error loading remote state:', e);
    return null;
  }
};

// Monitoramento de Heartbeat
export const updateScreenHeartbeat = async (screenId: string, syncId?: string) => {
  if (!syncId) return;
  try {
    await supabase.from('adcast_screens').update({ 
      last_seen: new Date().toISOString(),
      status: 'online'
    }).eq('id', screenId);
  } catch (e) {
    console.warn('⚠️ Heartbeat fail:', e);
  }
};

// Realtime Subscription
export const subscribeToProjectChanges = (syncId: string, callback: () => void) => {
  return supabase
    .channel(`project-realtime-${syncId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_media' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlists' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlist_items' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_screens' }, callback)
    .subscribe();
};

export const getLiveScreensStatus = async (syncId: string) => {
  try {
    const { data, error } = await supabase
      .from('adcast_screens')
      .select('id, last_seen')
      .eq('project_id', syncId);

    if (error) throw error;

    return data?.map(s => ({
      screen_id: s.id,
      last_seen: s.last_seen
    })) || [];
  } catch (e) {
    console.error('❌ Error fetching live status:', e);
    return [];
  }
};

// Diagnóstico Completo de Saúde
export const checkSupabaseHealth = async () => {
  try {
    const results = await Promise.all([
      supabase.from('adcast_media').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlists').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlist_items').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_screens').select('count', { count: 'exact', head: true })
    ]);

    const tables = {
      adcast_media: !results[0].error,
      adcast_playlists: !results[1].error,
      adcast_playlist_items: !results[2].error,
      adcast_screens: !results[3].error
    };

    const allOk = Object.values(tables).every(status => status === true);

    return { 
      connected: allOk,
      tables 
    };
  } catch (e: any) {
    return { 
      connected: false, 
      tables: { 
        adcast_media: false, 
        adcast_playlists: false, 
        adcast_playlist_items: false,
        adcast_screens: false 
      }, 
      error: e.message 
    };
  }
};

