import React, { useState, useEffect } from 'react';
import { ViewType, AppState } from './types';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ScreenManager } from './components/ScreenManager';
import { PlaylistManager } from './components/PlaylistManager';
import { MediaLibrary } from './components/MediaLibrary';
import { Player } from './components/Player';
import { loadState, saveState, loadRemoteState, subscribeToProjectChanges } from './services/storage';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [playerScreenId, setPlayerScreenId] = useState<string | null>(null);
  const [state, setState] = useState<AppState>(loadState());
  const [isLoading, setIsLoading] = useState(false);

  // Inicialização: Carrega dados remotos se houver syncId
  useEffect(() => {
    const init = async () => {
      if (state.syncId) {
        setIsLoading(true);
        const remote = await loadRemoteState(state.syncId);
        if (remote) {
          setState(remote);
        }
        setIsLoading(false);
      }
    };
    init();
  }, []);

  // Escuta mudanças em tempo real (Admin)
  useEffect(() => {
    if (state.syncId) {
      const sub = subscribeToProjectChanges(state.syncId, async () => {
        const remote = await loadRemoteState(state.syncId!);
        if (remote) setState(remote);
      });
      return () => { sub.unsubscribe(); };
    }
  }, [state.syncId]);

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash.startsWith('#player/')) {
        const id = hash.replace('#player/', '');
        setPlayerScreenId(id);
        setCurrentView('player');
      } else {
        setPlayerScreenId(null);
        if (hash === '#screens') setCurrentView('screens');
        else if (hash === '#playlists') setCurrentView('playlists');
        else if (hash === '#library') setCurrentView('library');
        else setCurrentView('dashboard');
      }
    };

    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();

    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const updateState = (newState: AppState) => {
    setState(newState);
    saveState(newState);
  };

  if (currentView === 'player' && playerScreenId) {
    return <Player screenId={playerScreenId} />;
  }

  const renderView = () => {
    if (isLoading) return (
      <div className="flex flex-col items-center justify-center h-96 gap-4">
        <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-slate-500 font-medium">Conectando ao banco de dados...</p>
      </div>
    );

    switch (currentView) {
      case 'dashboard':
        return <Dashboard state={state} onUpdate={updateState} />;
      case 'screens':
        return <ScreenManager state={state} onUpdate={updateState} />;
      case 'playlists':
        return <PlaylistManager state={state} onUpdate={updateState} />;
      case 'library':
        return <MediaLibrary state={state} onUpdate={updateState} />;
      default:
        return <Dashboard state={state} onUpdate={updateState} />;
    }
  };

  return (
    <Layout 
      currentView={currentView} 
      syncId={state.syncId}
      onViewChange={(v) => {
        window.location.hash = v;
        setCurrentView(v);
      }}
    >
      {renderView()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
