import React, { useState, useEffect, useRef } from 'react';
import { AppState, MediaItem } from '../types';
// Fixed: Removed non-existent loadState and added getActiveProjectId for session retrieval
import { getActiveProjectId, updateScreenHeartbeat, loadRemoteState, subscribeToProjectChanges } from '../services/storage';
import { Loader2, AlertCircle, RefreshCw, Monitor, Wifi, Zap } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isRemote, setIsRemote] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchData = async () => {
    const params = new URLSearchParams(window.location.search);
    const urlSyncId = params.get('sync');
    const savedSyncId = getActiveProjectId();
    const targetId = urlSyncId || savedSyncId;

    // Fixed: Replaced loadState call with loadRemoteState using targetId
    if (targetId) {
      const remoteState = await loadRemoteState(targetId);
      if (remoteState) {
        setState(remoteState);
        setIsRemote(true);
      }
      updateScreenHeartbeat(screenId, targetId);
    }

    setLoading(false);
  };

  useEffect(() => {
    fetchData();

    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    let subscription: any = null;
    if (syncId) {
      subscription = subscribeToProjectChanges(syncId, async () => {
        console.log('⚡ Relational update detected');
        const updated = await loadRemoteState(syncId);
        if (updated) setState(updated);
      });
    }

    const heartbeatInterval = setInterval(() => {
      // Fixed: Heartbeat now correctly checks for any available syncId
      const currentSyncId = syncId || getActiveProjectId() || state?.syncId;
      if (currentSyncId) {
        updateScreenHeartbeat(screenId, currentSyncId);
      }
    }, 30000);

    return () => {
      if (subscription) subscription.unsubscribe();
      clearInterval(heartbeatInterval);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId, state?.syncId]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight">Iniciando Terminal de Vídeo...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <h2 className="text-3xl font-bold text-white">Terminal não Registrado</h2>
        <p className="text-lg text-slate-500 max-w-md">ID: <span className="text-rose-400 font-mono">{screenId}</span></p>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white">
          Tentar Reconectar
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center">
        <Monitor size={100} className="mb-8 opacity-10" />
        <h2 className="text-3xl font-black text-white uppercase mb-2">Sem Programação</h2>
        <p className="mb-8 text-slate-400">{screen.name}</p>
        <div className="flex gap-4">
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-950 rounded-full border border-slate-800 text-xs text-emerald-500">
            <Wifi size={14} /> {isRemote ? 'Cloud Connected' : 'Local Only'}
          </div>
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  return (
    <div className="h-screen w-screen bg-black overflow-hidden relative select-none">
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000"
            key={activeItem.id}
          />
        ) : (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={() => setCurrentIndex((prev) => (prev + 1) % currentItems.length)}
          />
        )}
      </div>

      <div className="absolute bottom-8 left-8 z-50 flex items-center gap-3 bg-black/30 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full">
        <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.8)]" />
        <span className="text-white text-xs font-black uppercase tracking-widest">{screen.name}</span>
      </div>

      <div className="absolute bottom-0 left-0 h-1 bg-indigo-500/30 w-full z-50">
        <div 
          className="h-full bg-indigo-500"
          style={{ 
            width: '100%',
            animation: `progress ${(activeItem.duration || 10)}s linear infinite` 
          }}
          key={`${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
      `}</style>
    </div>
  );
};

import { AppState, MediaItem, Playlist, Screen } from '../types';
import { INITIAL_MEDIA, INITIAL_PLAYLISTS, INITIAL_SCREENS } from '../constants';
import { supabase } from './supabase';

const STORAGE_PROJECT_KEY = 'adcast_project_id';

export const getActiveProjectId = (): string | null => {
  return localStorage.getItem(STORAGE_PROJECT_KEY);
};

export const setActiveProjectId = (id: string | null) => {
  if (id) localStorage.setItem(STORAGE_PROJECT_KEY, id);
  else localStorage.removeItem(STORAGE_PROJECT_KEY);
};

export const loadRemoteState = async (projectId: string): Promise<AppState | null> => {
  try {
    const [mediaRes, playlistRes, screensRes] = await Promise.all([
      supabase.from('adcast_media').select('*').eq('project_id', projectId),
      supabase.from('adcast_playlists').select('*').eq('project_id', projectId),
      supabase.from('adcast_screens').select('*').eq('project_id', projectId)
    ]);

    if (mediaRes.error || playlistRes.error || screensRes.error) throw new Error('Falha na busca remota');

    const playlistIds = playlistRes.data.map(p => p.id);
    const playlistItemsRes = playlistIds.length > 0 
      ? await supabase.from('adcast_playlist_items').select('*').in('playlist_id', playlistIds)
      : { data: [], error: null };

    const playlists: Playlist[] = playlistRes.data.map(p => {
      const items = playlistItemsRes.data
        ?.filter(pi => pi.playlist_id === p.id)
        .sort((a, b) => a.position - b.position)
        .map(pi => pi.media_id) || [];

      return { id: p.id, name: p.name, items };
    });

    return {
      syncId: projectId,
      library: mediaRes.data.map(m => ({
        id: m.id,
        name: m.name,
        url: m.url,
        type: m.type,
        duration: m.duration,
        createdAt: new Date(m.created_at).getTime()
      })),
      playlists: playlists,
      screens: screensRes.data.map(s => ({
        id: s.id,
        name: s.name,
        currentPlaylistId: s.current_playlist_id,
        status: (Date.now() - new Date(s.last_seen).getTime() < 60000) ? 'online' : 'offline',
        lastSeen: new Date(s.last_seen).getTime()
      }))
    };
  } catch (e) {
    console.error('❌ Erro ao carregar estado remoto:', e);
    return null;
  }
};

export const saveStateToCloud = async (state: AppState) => {
  if (!state.syncId) return;
  try {
    const projectId = state.syncId;
    if (state.library.length > 0) {
      await supabase.from('adcast_media').upsert(
        state.library.map(m => ({
          id: m.id,
          project_id: projectId,
          name: m.name,
          url: m.url,
          type: m.type,
          duration: m.duration
        }))
      );
    }
    if (state.playlists.length > 0) {
      await supabase.from('adcast_playlists').upsert(
        state.playlists.map(p => ({ id: p.id, project_id: projectId, name: p.name }))
      );
      for (const playlist of state.playlists) {
        await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlist.id);
        if (playlist.items.length > 0) {
          await supabase.from('adcast_playlist_items').insert(
            playlist.items.map((mediaId, index) => ({
              playlist_id: playlist.id,
              media_id: mediaId,
              position: index
            }))
          );
        }
      }
    }
    if (state.screens.length > 0) {
      await supabase.from('adcast_screens').upsert(
        state.screens.map(s => ({
          id: s.id,
          project_id: projectId,
          name: s.name,
          current_playlist_id: s.currentPlaylistId,
          status: s.status,
          last_seen: new Date(s.lastSeen).toISOString()
        }))
      );
    }
  } catch (e) {
    console.error('❌ Erro na Sincronização Cloud:', e);
  }
};

// --- FUNÇÕES DE DELEÇÃO REALTIME ---

export const deleteMediaFromCloud = async (mediaId: string) => {
  // Primeiro removemos as referências nas playlists para evitar erro de FK
  await supabase.from('adcast_playlist_items').delete().eq('media_id', mediaId);
  // Depois removemos a mídia
  const { error } = await supabase.from('adcast_media').delete().eq('id', mediaId);
  if (error) throw error;
};

export const deletePlaylistFromCloud = async (playlistId: string) => {
  // Remove itens da playlist primeiro
  await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlistId);
  // Remove a playlist
  const { error } = await supabase.from('adcast_playlists').delete().eq('id', playlistId);
  if (error) throw error;
};

export const deleteScreenFromCloud = async (screenId: string) => {
  const { error } = await supabase.from('adcast_screens').delete().eq('id', screenId);
  if (error) throw error;
};

export const createNewProject = async (): Promise<string | null> => {
  const projectId = `prj-${Math.random().toString(36).substr(2, 9)}`;
  try {
    await supabase.from('adcast_media').insert(
      INITIAL_MEDIA.map(m => ({ 
        id: m.id, 
        name: m.name, 
        url: m.url, 
        type: m.type, 
        duration: m.duration, 
        project_id: projectId 
      }))
    );
    await supabase.from('adcast_playlists').insert(
      INITIAL_PLAYLISTS.map(p => ({ id: p.id, name: p.name, project_id: projectId }))
    );
    for (const p of INITIAL_PLAYLISTS) {
      await supabase.from('adcast_playlist_items').insert(
        p.items.map((mid, idx) => ({ playlist_id: p.id, media_id: mid, position: idx }))
      );
    }
    return projectId;
  } catch (e) {
    console.error('Erro ao criar projeto:', e);
    return null;
  }
};

export const updateScreenHeartbeat = async (screenId: string, syncId?: string, screenName?: string) => {
  if (!syncId) return;
  try {
    await supabase.from('adcast_screens').upsert({ 
      id: screenId,
      project_id: syncId,
      name: screenName || 'Tela Remota',
      last_seen: new Date().toISOString(),
      status: 'online'
    }, { onConflict: 'id' });
  } catch (e) {
    console.warn('⚠️ Falha no Heartbeat:', e);
  }
};

export const subscribeToProjectChanges = (syncId: string, callback: () => void) => {
  return supabase
    .channel(`project-realtime-${syncId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_media' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlists' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlist_items' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_screens' }, callback)
    .subscribe();
};

export const getLiveScreensStatus = async (syncId: string) => {
  try {
    const { data, error } = await supabase
      .from('adcast_screens')
      .select('id, last_seen')
      .eq('project_id', syncId);
    if (error) throw error;
    return data?.map(s => ({ screen_id: s.id, last_seen: s.last_seen })) || [];
  } catch (e) {
    return [];
  }
};

export const checkSupabaseHealth = async () => {
  try {
    const results = await Promise.all([
      supabase.from('adcast_media').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlists').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlist_items').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_screens').select('count', { count: 'exact', head: true })
    ]);
    const tables = {
      'Mídias': !results[0].error,
      'Playlists': !results[1].error,
      'Itens': !results[2].error,
      'Telas': !results[3].error
    };
    return { connected: Object.values(tables).every(s => s === true), tables };
  } catch (e) {
    return { connected: false, tables: {} };
  }
};

