import React, { useState, useEffect, useRef } from 'react';
import { AppState, MediaItem } from '../types';
import { getActiveProjectId, updateScreenHeartbeat, loadRemoteState, subscribeToProjectChanges } from '../services/storage';
import { Loader2, AlertCircle, Monitor, Wifi, Code2 } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [isRemote, setIsRemote] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const fetchData = async () => {
    const params = new URLSearchParams(window.location.search);
    const urlSyncId = params.get('sync');
    const savedSyncId = getActiveProjectId();
    const targetId = urlSyncId || savedSyncId;

    if (targetId) {
      const remoteState = await loadRemoteState(targetId);
      if (remoteState) {
        setState(remoteState);
        setIsRemote(true);
      }
      updateScreenHeartbeat(screenId, targetId);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    let subscription: any = null;
    if (syncId) {
      subscription = subscribeToProjectChanges(syncId, async () => {
        const updated = await loadRemoteState(syncId);
        if (updated) setState(updated);
      });
    }

    const heartbeatInterval = setInterval(() => {
      const currentSyncId = syncId || getActiveProjectId() || state?.syncId;
      if (currentSyncId) {
        updateScreenHeartbeat(screenId, currentSyncId);
      }
    }, 30000);

    return () => {
      if (subscription) subscription.unsubscribe();
      clearInterval(heartbeatInterval);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId, state?.syncId]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight">Sincronizando Terminal Cloud...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <h2 className="text-3xl font-bold text-white">Terminal não Registrado</h2>
        <p className="text-lg text-slate-500 max-w-md">ID: <span className="text-rose-400 font-mono">{screenId}</span></p>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white">
          Tentar Reconectar
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center">
        <Monitor size={100} className="mb-8 opacity-10" />
        <h2 className="text-3xl font-black text-white uppercase mb-2">Sem Programação Cloud</h2>
        <p className="mb-8 text-slate-400">{screen.name}</p>
        <div className="flex items-center gap-2 px-4 py-2 bg-slate-950 rounded-full border border-slate-800 text-xs text-emerald-500">
          <Wifi size={14} /> Conectado ao Workspace
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  return (
    <div className="h-screen w-screen bg-black overflow-hidden relative select-none">
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000"
            key={activeItem.id}
          />
        ) : activeItem.type === 'video' ? (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={() => setCurrentIndex((prev) => (prev + 1) % currentItems.length)}
          />
        ) : (
          <div 
            className="w-full h-full flex items-center justify-center bg-white"
            dangerouslySetInnerHTML={{ __html: activeItem.url }}
            key={activeItem.id}
          />
        )}
      </div>

      <div className="absolute bottom-8 left-8 z-50 flex items-center gap-3 bg-black/30 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full">
        <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.8)]" />
        <span className="text-white text-xs font-black uppercase tracking-widest">{screen.name}</span>
        {activeItem.type === 'html' && <Code2 size={12} className="text-indigo-400" />}
      </div>

      <div className="absolute bottom-0 left-0 h-1 bg-indigo-500/30 w-full z-50">
        <div 
          className="h-full bg-indigo-500"
          style={{ 
            width: '100%',
            animation: `progress ${(activeItem.duration || 10)}s linear infinite` 
          }}
          key={`${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
        /* Garantir que iframes de widgets ocupem o container se não tiverem largura fixa */
        .w-full iframe {
          max-width: 100%;
        }
      `}</style>
    </div>
  );
};

import { AppState, MediaItem, Playlist, Screen } from '../types';
import { INITIAL_MEDIA, INITIAL_PLAYLISTS, INITIAL_SCREENS } from '../constants';
import { supabase } from './supabase';

const STORAGE_PROJECT_KEY = 'adcast_project_id';

export const getActiveProjectId = (): string | null => {
  return localStorage.getItem(STORAGE_PROJECT_KEY);
};

export const setActiveProjectId = (id: string | null) => {
  if (id) localStorage.setItem(STORAGE_PROJECT_KEY, id);
  else localStorage.removeItem(STORAGE_PROJECT_KEY);
};

export const loadRemoteState = async (projectId: string): Promise<AppState | null> => {
  try {
    const [mediaRes, playlistRes, screensRes] = await Promise.all([
      supabase.from('adcast_media').select('*').eq('project_id', projectId),
      supabase.from('adcast_playlists').select('*').eq('project_id', projectId),
      supabase.from('adcast_screens').select('*').eq('project_id', projectId)
    ]);

    if (mediaRes.error) throw mediaRes.error;
    if (playlistRes.error) throw playlistRes.error;
    if (screensRes.error) throw screensRes.error;

    const playlistIds = playlistRes.data.map(p => p.id);
    const playlistItemsRes = playlistIds.length > 0 
      ? await supabase.from('adcast_playlist_items').select('*').in('playlist_id', playlistIds)
      : { data: [], error: null };

    if (playlistItemsRes.error) throw playlistItemsRes.error;

    const playlists: Playlist[] = playlistRes.data.map(p => {
      const items = playlistItemsRes.data
        ?.filter(pi => pi.playlist_id === p.id)
        .sort((a, b) => a.position - b.position)
        .map(pi => pi.media_id) || [];

      return { id: p.id, name: p.name, items };
    });

    return {
      syncId: projectId,
      library: mediaRes.data.map(m => ({
        id: m.id,
        name: m.name,
        url: m.url,
        type: m.type as any,
        duration: m.duration,
        createdAt: new Date(m.created_at).getTime()
      })),
      playlists: playlists,
      screens: screensRes.data.map(s => ({
        id: s.id,
        name: s.name,
        currentPlaylistId: s.current_playlist_id,
        status: (Date.now() - new Date(s.last_seen).getTime() < 60000) ? 'online' : 'offline',
        lastSeen: new Date(s.last_seen).getTime()
      }))
    };
  } catch (e) {
    console.error('❌ Erro ao carregar estado remoto:', e);
    return null;
  }
};

export const saveStateToCloud = async (state: AppState) => {
  if (!state.syncId) return;
  try {
    const projectId = state.syncId;

    // Sincronizar Mídias
    if (state.library.length > 0) {
      const { error: mediaError } = await supabase.from('adcast_media').upsert(
        state.library.map(m => ({
          id: m.id,
          project_id: projectId,
          name: m.name,
          url: m.url,
          type: m.type,
          duration: m.duration
        })),
        { onConflict: 'id' }
      );
      if (mediaError) throw mediaError;
    }

    // Sincronizar Playlists
    if (state.playlists.length > 0) {
      const { error: playlistError } = await supabase.from('adcast_playlists').upsert(
        state.playlists.map(p => ({ id: p.id, project_id: projectId, name: p.name })),
        { onConflict: 'id' }
      );
      if (playlistError) throw playlistError;

      for (const playlist of state.playlists) {
        // Limpar itens antigos e inserir novos para garantir ordem
        const { error: deleteItemsError } = await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlist.id);
        if (deleteItemsError) throw deleteItemsError;

        if (playlist.items.length > 0) {
          const { error: insertItemsError } = await supabase.from('adcast_playlist_items').insert(
            playlist.items.map((mediaId, index) => ({
              playlist_id: playlist.id,
              media_id: mediaId,
              position: index
            }))
          );
          if (insertItemsError) throw insertItemsError;
        }
      }
    }

    // Sincronizar Telas
    if (state.screens.length > 0) {
      const { error: screensError } = await supabase.from('adcast_screens').upsert(
        state.screens.map(s => ({
          id: s.id,
          project_id: projectId,
          name: s.name,
          current_playlist_id: s.currentPlaylistId,
          status: s.status,
          last_seen: new Date(s.lastSeen).toISOString()
        })),
        { onConflict: 'id' }
      );
      if (screensError) throw screensError;
    }
  } catch (e) {
    console.error('❌ Erro na Sincronização Cloud:', e);
    throw e; // Repassa o erro para o App.tsx tratar com UI
  }
};

export const deleteMediaFromCloud = async (mediaId: string) => {
  await supabase.from('adcast_playlist_items').delete().eq('media_id', mediaId);
  const { error } = await supabase.from('adcast_media').delete().eq('id', mediaId);
  if (error) throw error;
};

export const deletePlaylistFromCloud = async (playlistId: string) => {
  await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlistId);
  const { error } = await supabase.from('adcast_playlists').delete().eq('id', playlistId);
  if (error) throw error;
};

export const deleteScreenFromCloud = async (screenId: string) => {
  const { error } = await supabase.from('adcast_screens').delete().eq('id', screenId);
  if (error) throw error;
};

export const createNewProject = async (): Promise<string | null> => {
  const projectId = `prj-${Math.random().toString(36).substr(2, 9)}`;
  try {
    const { error: mError } = await supabase.from('adcast_media').insert(
      INITIAL_MEDIA.map(m => ({ 
        id: m.id, 
        name: m.name, 
        url: m.url, 
        type: m.type, 
        duration: m.duration, 
        project_id: projectId 
      }))
    );
    if (mError) throw mError;

    const { error: pError } = await supabase.from('adcast_playlists').insert(
      INITIAL_PLAYLISTS.map(p => ({ id: p.id, name: p.name, project_id: projectId }))
    );
    if (pError) throw pError;

    for (const p of INITIAL_PLAYLISTS) {
      const { error: piError } = await supabase.from('adcast_playlist_items').insert(
        p.items.map((mid, idx) => ({ playlist_id: p.id, media_id: mid, position: idx }))
      );
      if (piError) throw piError;
    }
    return projectId;
  } catch (e) {
    console.error('Erro ao criar projeto:', e);
    return null;
  }
};

export const updateScreenHeartbeat = async (screenId: string, syncId?: string, screenName?: string) => {
  if (!syncId) return;
  try {
    await supabase.from('adcast_screens').upsert({ 
      id: screenId,
      project_id: syncId,
      name: screenName || 'Tela Remota',
      last_seen: new Date().toISOString(),
      status: 'online'
    }, { onConflict: 'id' });
  } catch (e) {
    console.warn('⚠️ Falha no Heartbeat:', e);
  }
};

export const subscribeToProjectChanges = (syncId: string, callback: () => void) => {
  return supabase
    .channel(`project-realtime-${syncId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_media' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlists' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlist_items' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_screens' }, callback)
    .subscribe();
};

export const getLiveScreensStatus = async (syncId: string) => {
  try {
    const { data, error } = await supabase
      .from('adcast_screens')
      .select('id, last_seen')
      .eq('project_id', syncId);
    if (error) throw error;
    return data?.map(s => ({ screen_id: s.id, last_seen: s.last_seen })) || [];
  } catch (e) {
    return [];
  }
};

export const checkSupabaseHealth = async () => {
  try {
    const results = await Promise.all([
      supabase.from('adcast_media').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlists').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlist_items').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_screens').select('count', { count: 'exact', head: true })
    ]);
    const tables = {
      'Mídias': !results[0].error,
      'Playlists': !results[1].error,
      'Itens': !results[2].error,
      'Telas': !results[3].error
    };
    return { connected: Object.values(tables).every(s => s === true), tables };
  } catch (e) {
    return { connected: false, tables: {} };
  }
};

import React, { useState, useEffect } from 'react';
import { ViewType, AppState } from './types';
import { Layout } from './components/Layout';
import { Dashboard } from './components/Dashboard';
import { ScreenManager } from './components/ScreenManager';
import { PlaylistManager } from './components/PlaylistManager';
import { MediaLibrary } from './components/MediaLibrary';
import { Player } from './components/Player';
import { Button } from './components/ui/Button';
import { 
  loadRemoteState, 
  subscribeToProjectChanges, 
  getActiveProjectId, 
  setActiveProjectId, 
  createNewProject,
  saveStateToCloud 
} from './services/storage';
import { Cloud, Loader2, Database, Plus, LogIn } from 'lucide-react';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [playerScreenId, setPlayerScreenId] = useState<string | null>(null);
  const [state, setState] = useState<AppState | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [inputProjectId, setInputProjectId] = useState('');

  // Carrega o projeto ativo ou da URL
  useEffect(() => {
    const init = async () => {
      const urlParams = new URLSearchParams(window.location.search);
      const urlSyncId = urlParams.get('sync');
      const savedSyncId = getActiveProjectId();
      const targetId = urlSyncId || savedSyncId;

      if (targetId) {
        const remote = await loadRemoteState(targetId);
        if (remote) {
          setState(remote);
          setActiveProjectId(targetId);
        }
      }
      setIsLoading(false);
    };
    init();
  }, []);

  // Escuta mudanças em tempo real do Supabase
  useEffect(() => {
    if (state?.syncId) {
      const sub = subscribeToProjectChanges(state.syncId, async () => {
        const remote = await loadRemoteState(state.syncId!);
        if (remote) setState(remote);
      });
      return () => { sub.unsubscribe(); };
    }
  }, [state?.syncId]);

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash.startsWith('#player/')) {
        const id = hash.replace('#player/', '');
        setPlayerScreenId(id);
        setCurrentView('player');
      } else {
        setPlayerScreenId(null);
        if (hash === '#screens') setCurrentView('screens');
        else if (hash === '#playlists') setCurrentView('playlists');
        else if (hash === '#library') setCurrentView('library');
        else setCurrentView('dashboard');
      }
    };
    window.addEventListener('hashchange', handleHashChange);
    handleHashChange();
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const updateState = async (newState: AppState) => {
    const previousState = state;
    setState(newState);
    try {
      await saveStateToCloud(newState);
    } catch (err: any) {
      console.error('Falha ao sincronizar:', err);
      alert(`Erro ao salvar na nuvem: ${err.message || 'Verifique sua conexão ou permissões do banco.'}`);
      setState(previousState); // Rollback local se falhar na nuvem
    }
  };

  const handleCreateProject = async () => {
    setIsLoading(true);
    const newId = await createNewProject();
    if (newId) {
      const remote = await loadRemoteState(newId);
      setState(remote);
      setActiveProjectId(newId);
      // Limpa URL para evitar conflitos
      window.history.replaceState({}, '', window.location.pathname);
    }
    setIsLoading(false);
  };

  const handleJoinProject = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputProjectId.trim()) return;
    setIsLoading(true);
    const remote = await loadRemoteState(inputProjectId.trim());
    if (remote) {
      setState(remote);
      setActiveProjectId(inputProjectId.trim());
    } else {
      alert('ID de projeto não encontrado ou erro de conexão.');
    }
    setIsLoading(false);
  };

  // Se estiver no modo player, ignora tela de login
  if (currentView === 'player' && playerScreenId) {
    return <Player screenId={playerScreenId} />;
  }

  // Tela de Boas-vindas / Seleção de Projeto
  if (!state && !isLoading) {
    return (
      <div className="h-screen w-screen bg-slate-950 flex items-center justify-center p-6">
        <div className="max-w-md w-full space-y-8 text-center">
          <div className="flex flex-col items-center gap-4">
            <div className="p-4 bg-indigo-600 rounded-2xl shadow-2xl shadow-indigo-500/20">
              <Database size={48} className="text-white" />
            </div>
            <h1 className="text-4xl font-black text-white tracking-tighter italic">ADCAST CLOUD</h1>
            <p className="text-slate-400 font-medium">Sua infraestrutura de sinalização digital 100% na nuvem.</p>
          </div>

          <div className="bg-slate-900 border border-slate-800 p-8 rounded-3xl shadow-2xl space-y-6">
            <form onSubmit={handleJoinProject} className="space-y-4 text-left">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest px-1">Entrar em Projeto Existente</label>
              <div className="flex gap-2">
                <input 
                  type="text"
                  value={inputProjectId}
                  onChange={e => setInputProjectId(e.target.value)}
                  placeholder="Insira o Token do Projeto..."
                  className="flex-1 bg-slate-950 border border-slate-800 rounded-xl px-4 py-3 text-sm text-white focus:ring-2 focus:ring-indigo-500 outline-none"
                />
                <Button type="submit" variant="primary" icon={<LogIn size={18} />}>Entrar</Button>
              </div>
            </form>

            <div className="relative">
              <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-800"></div></div>
              <div className="relative flex justify-center text-[10px] uppercase font-bold text-slate-600 bg-slate-900 px-2">ou</div>
            </div>

            <Button 
              className="w-full py-4 text-base" 
              variant="secondary" 
              icon={<Plus size={20} />}
              onClick={handleCreateProject}
            >
              Criar Novo Workspace
            </Button>
          </div>

          <p className="text-[10px] text-slate-600 font-mono italic">
            Conectado a Supabase: https://lrdqisnuifbvrjfkwbzv.supabase.co
          </p>
        </div>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="h-screen w-screen bg-slate-950 flex flex-col items-center justify-center gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-slate-500 font-medium animate-pulse">Estabelecendo conexão segura...</p>
      </div>
    );
  }

  const renderView = () => {
    if (!state) return null;
    switch (currentView) {
      case 'dashboard': return <Dashboard state={state} onUpdate={updateState} />;
      case 'screens': return <ScreenManager state={state} onUpdate={updateState} />;
      case 'playlists': return <PlaylistManager state={state} onUpdate={updateState} />;
      case 'library': return <MediaLibrary state={state} onUpdate={updateState} />;
      default: return <Dashboard state={state} onUpdate={updateState} />;
    }
  };

  return (
    <Layout 
      currentView={currentView} 
      syncId={state?.syncId}
      onViewChange={(v) => {
        window.location.hash = v;
        setCurrentView(v);
      }}
    >
      {renderView()}
    </Layout>
  );
};

