interface MediaLibraryProps {
  state: AppState;
  onUpdate: (newState: AppState) => Promise<void>;
}

export const MediaLibrary: React.FC<MediaLibraryProps> = ({ state, onUpdate }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [newMedia, setNewMedia] = useState({
    name: '',
    url: '',
    type: 'image' as MediaType,
    duration: 10
  });

  const handleAddMedia = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMedia.name || !newMedia.url) return;

    setIsSaving(true);
    const newItem: MediaItem = {
      id: `m-${Date.now()}`,
      name: newMedia.name,
      url: newMedia.url,
      type: newMedia.type,
      duration: newMedia.duration,
      createdAt: Date.now()
    };

    try {
      await onUpdate({
        ...state,
        library: [newItem, ...state.library]
      });
      setNewMedia({ name: '', url: '', type: 'image', duration: 10 });
      setShowAddForm(false);
    } catch (err) {
      // O erro já é alertado pelo App.tsx
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteMedia = async (id: string) => {
    if (confirm('Tem certeza que deseja excluir esta mídia? Ela será removida de todas as playlists.')) {
      try {
        await deleteMediaFromCloud(id);
      } catch (err: any) {
        alert('Erro ao excluir mídia: ' + err.message);
      }
    }
  };

  const getHostnameSafely = (url: string, type: MediaType) => {
    if (type === 'html') return 'Widget/Snippet';
    try {
      return new URL(url).hostname;
    } catch (e) {
      return 'URL Customizada';
    }
  };

  return (
    <div className="space-y-6">
