                  value={newMedia.duration}
                  onChange={e => setNewMedia({...newMedia, duration: parseInt(e.target.value) || 10})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none disabled:opacity-50"
                />
              </div>
            </div>

            <div className="space-y-2">
              <label className="text-xs font-semibold text-slate-400 uppercase">
                {newMedia.type === 'html' ? 'Código HTML / Iframe' : 'URL da Mídia'}
              </label>
              {newMedia.type === 'html' ? (
                <textarea 
                  required
                  rows={4}
                  disabled={isSaving}
                  value={newMedia.url}
                  onChange={e => setNewMedia({...newMedia, url: e.target.value})}
                  placeholder="Cole aqui o <iframe> ou código HTML..."
                  className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-sm text-indigo-300 font-mono focus:ring-1 focus:ring-indigo-500 outline-none disabled:opacity-50"
