        {state.library.map((item) => (
          <div key={item.id} className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden group hover:border-indigo-500/50 transition-all">
            <div className="aspect-video relative overflow-hidden bg-slate-950">
              {item.type === 'image' ? (
                <img src={item.url} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
              ) : item.type === 'video' ? (
                <div className="w-full h-full flex items-center justify-center">
                  <Film size={40} className="text-slate-700" />
                </div>
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950 text-indigo-500/50">
                  <Code2 size={40} />
                  <span className="text-[10px] font-mono mt-2 uppercase tracking-widest">HTML Widget</span>
                </div>
              )}
              <div className="absolute top-2 right-2 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button 
                  onClick={() => handleDeleteMedia(item.id)}
                  className="p-2 bg-rose-600 text-white rounded-lg hover:bg-rose-700 transition-colors shadow-lg"
                >
                  <Trash2 size={16} />
                </button>
              </div>
              <div className="absolute bottom-2 left-2">
                <span className="px-2 py-1 bg-black/60 backdrop-blur-md rounded text-[10px] font-bold uppercase text-white border border-white/10 flex items-center gap-1">
                  {item.type === 'image' ? <ImageIcon size={10} /> : item.type === 'video' ? <Film size={10} /> : <Code2 size={10} />}
                  {item.type === 'image' ? 'Imagem' : item.type === 'video' ? 'Vídeo' : 'HTML'}
                </span>
              </div>
            </div>

            <div className="p-4">
              <h4 className="font-bold text-white truncate mb-1">{item.name}</h4>
              <div className="flex items-center justify-between text-slate-500 text-xs">
                <div className="flex items-center gap-1">
                  <Clock size={12} />
                  <span>{item.duration}s</span>
                </div>
                <span className="truncate max-w-[120px]">
                  {getHostnameSafely(item.url, item.type)}
                </span>
              </div>
            </div>
          </div>
        ))}

        {state.library.length === 0 && (
          <div className="col-span-full py-20 flex flex-col items-center justify-center border-2 border-dashed border-slate-800 rounded-3xl text-slate-500">
            <ImageIcon size={48} className="mb-4 opacity-20" />
            <p>Sua biblioteca está vazia.</p>
          </div>
        )}
      </div>
    </div>
  );
};

