Para resolver o problema de o **Código HTML / Widget** não estar salvando e garantir que seu banco de dados Supabase esteja 100% correto para todas as funcionalidades (incluindo as tabelas de playlists e telas), siga os passos abaixo.

O erro que você recebeu anteriormente (`already member of publication`) aconteceu porque o script tentou habilitar o Realtime em algo que já estava habilitado. O script abaixo é "inteligente": ele verifica se a tabela já tem a restrição correta e se o Realtime já está ativo antes de tentar criar.

### 1. Script SQL Corrigido para o Supabase
Execute este código no seu **SQL Editor** do Supabase. Ele garante que a coluna `url` aceite textos longos (como códigos HTML) e que o tipo `html` seja permitido.

```sql
-- 1. GARANTIR QUE AS TABELAS EXISTEM COM AS COLUNAS CORRETAS
CREATE TABLE IF NOT EXISTS public.adcast_media (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    name TEXT NOT NULL,
    url TEXT NOT NULL, -- TEXT em Postgres é ilimitado, ideal para códigos HTML
    type TEXT NOT NULL,
    duration INTEGER DEFAULT 10,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.adcast_playlists (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    name TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.adcast_playlist_items (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    playlist_id TEXT REFERENCES public.adcast_playlists(id) ON DELETE CASCADE,
    media_id TEXT REFERENCES public.adcast_media(id) ON DELETE CASCADE,
    position INTEGER NOT NULL
);

CREATE TABLE IF NOT EXISTS public.adcast_screens (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    name TEXT NOT NULL,
    current_playlist_id TEXT REFERENCES public.adcast_playlists(id) ON DELETE SET NULL,
    status TEXT DEFAULT 'offline',
    last_seen TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. ATUALIZAR A RESTRIÇÃO DE TIPO (Caso você tenha criado antes sem o 'html')
ALTER TABLE public.adcast_media DROP CONSTRAINT IF EXISTS adcast_media_type_check;
ALTER TABLE public.adcast_media ADD CONSTRAINT adcast_media_type_check CHECK (type IN ('image', 'video', 'html'));

-- 3. HABILITAR REALTIME (Com verificação para evitar o erro 42710)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'adcast_media') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.adcast_media;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'adcast_playlists') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.adcast_playlists;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'adcast_playlist_items') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.adcast_playlist_items;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname = 'supabase_realtime' AND tablename = 'adcast_screens') THEN
        ALTER PUBLICATION supabase_realtime ADD TABLE public.adcast_screens;
    END IF;
END $$;
```

