CREATE TABLE IF NOT EXISTS adcast_media (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  url TEXT NOT NULL,
  type TEXT NOT NULL,
  duration INTEGER NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Tabela de Playlists
CREATE TABLE IF NOT EXISTS adcast_playlists (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 3. Tabela de Itens da Playlist (Relação N:N)
CREATE TABLE IF NOT EXISTS adcast_playlist_items (
  id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  playlist_id TEXT REFERENCES adcast_playlists(id) ON DELETE CASCADE,
  media_id TEXT REFERENCES adcast_media(id) ON DELETE CASCADE,
  position INTEGER NOT NULL
);

-- 4. Tabela de Telas (Terminais)
CREATE TABLE IF NOT EXISTS adcast_screens (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  current_playlist_id TEXT REFERENCES adcast_playlists(id) ON DELETE SET NULL,
  status TEXT NOT NULL,
  last_seen TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Habilitar Realtime para as tabelas (Crucial para as TVs atualizarem sozinhas)
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE adcast_media;
    ALTER PUBLICATION supabase_realtime ADD TABLE adcast_playlists;
    ALTER PUBLICATION supabase_realtime ADD TABLE adcast_playlist_items;
    ALTER PUBLICATION supabase_realtime ADD TABLE adcast_screens;
  END IF;
EXCEPTION
  WHEN others THEN 
    RAISE NOTICE 'Não foi possível habilitar via SQL. Ative o Realtime manualmente no painel.';
END $$;

/**
 * ESQUEMA SQL PARA SUPABASE (Execute no SQL Editor):
 * 
 * -- 1. Tabela de Mídias
 * create table adcast_media (
 *   id text primary key,
 *   project_id text not null,
 *   name text not null,
 *   url text not null,
 *   type text not null,
 *   duration integer not null,
 *   created_at timestamp with time zone default now()
 * );
 * 
 * -- 2. Tabela de Playlists
 * create table adcast_playlists (
 *   id text primary key,
 *   project_id text not null,
 *   name text not null,
 *   created_at timestamp with time zone default now()
 * );
 * 
 * -- 3. Tabela de Itens da Playlist (Relação N:N)
 * create table adcast_playlist_items (
 *   id bigint primary key generated always as identity,
 *   playlist_id text references adcast_playlists(id) on delete cascade,
 *   media_id text references adcast_media(id) on delete cascade,
 *   position integer not null
 * );
 * 
 * -- 4. Tabela de Telas (Terminais)
 * create table adcast_screens (
 *   id text primary key,
 *   project_id text not null,
 *   name text not null,
 *   current_playlist_id text references adcast_playlists(id) on delete set null,
 *   status text not null,
 *   last_seen timestamp with time zone default now()
 * );
 */

import { AppState, MediaItem, Playlist, Screen } from '../types';
import { INITIAL_MEDIA, INITIAL_PLAYLISTS, INITIAL_SCREENS } from '../constants';
import { supabase } from './supabase';

const STORAGE_PROJECT_KEY = 'adcast_project_id';

export const getActiveProjectId = (): string | null => {
  return localStorage.getItem(STORAGE_PROJECT_KEY);
};

export const setActiveProjectId = (id: string | null) => {
  if (id) localStorage.setItem(STORAGE_PROJECT_KEY, id);
  else localStorage.removeItem(STORAGE_PROJECT_KEY);
};

export const loadRemoteState = async (projectId: string): Promise<AppState | null> => {
  try {
    const [mediaRes, playlistRes, screensRes] = await Promise.all([
      supabase.from('adcast_media').select('*').eq('project_id', projectId),
      supabase.from('adcast_playlists').select('*').eq('project_id', projectId),
      supabase.from('adcast_screens').select('*').eq('project_id', projectId)
    ]);

    if (mediaRes.error) throw mediaRes.error;
    if (playlistRes.error) throw playlistRes.error;
    if (screensRes.error) throw screensRes.error;

    const playlistIds = playlistRes.data.map(p => p.id);
    const playlistItemsRes = playlistIds.length > 0 
      ? await supabase.from('adcast_playlist_items').select('*').in('playlist_id', playlistIds)
      : { data: [], error: null };

    if (playlistItemsRes.error) throw playlistItemsRes.error;

    const playlists: Playlist[] = playlistRes.data.map(p => {
      const items = playlistItemsRes.data
        ?.filter(pi => pi.playlist_id === p.id)
        .sort((a, b) => a.position - b.position)
        .map(pi => pi.media_id) || [];

      return { id: p.id, name: p.name, items };
    });

    return {
      syncId: projectId,
      library: mediaRes.data.map(m => ({
        id: m.id,
        name: m.name,
        url: m.url,
        type: m.type as any,
        duration: m.duration,
        createdAt: new Date(m.created_at).getTime()
      })),
      playlists: playlists,
      screens: screensRes.data.map(s => ({
        id: s.id,
        name: s.name,
        currentPlaylistId: s.current_playlist_id,
        status: (Date.now() - new Date(s.last_seen).getTime() < 60000) ? 'online' : 'offline',
        lastSeen: new Date(s.last_seen).getTime()
      }))
    };
  } catch (e) {
    console.error('❌ Erro ao carregar estado remoto:', e);
    return null;
  }
};

export const saveStateToCloud = async (state: AppState) => {
  if (!state.syncId) return;
  try {
    const projectId = state.syncId;

    // Sincronizar Mídias
    if (state.library.length > 0) {
      const mediaToUpsert = state.library.map(m => ({
        id: m.id,
        project_id: projectId,
        name: m.name,
        url: m.url,
        type: m.type,
        duration: m.duration
      }));

      const { error: mediaError } = await supabase
        .from('adcast_media')
        .upsert(mediaToUpsert, { onConflict: 'id' });

      if (mediaError) {
        console.error('Erro detalhado ao salvar mídia:', mediaError);
        throw mediaError;
      }
    }

    // Sincronizar Playlists
    if (state.playlists.length > 0) {
      const { error: playlistError } = await supabase.from('adcast_playlists').upsert(
        state.playlists.map(p => ({ id: p.id, project_id: projectId, name: p.name })),
        { onConflict: 'id' }
      );
      if (playlistError) throw playlistError;

      for (const playlist of state.playlists) {
        // Limpar itens antigos e inserir novos para garantir ordem
        const { error: deleteItemsError } = await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlist.id);
        if (deleteItemsError) throw deleteItemsError;

        if (playlist.items.length > 0) {
          const { error: insertItemsError } = await supabase.from('adcast_playlist_items').insert(
            playlist.items.map((mediaId, index) => ({
              playlist_id: playlist.id,
              media_id: mediaId,
              position: index
            }))
          );
          if (insertItemsError) throw insertItemsError;
        }
      }
    }

    // Sincronizar Telas
    if (state.screens.length > 0) {
      const { error: screensError } = await supabase.from('adcast_screens').upsert(
        state.screens.map(s => ({
          id: s.id,
          project_id: projectId,
          name: s.name,
          current_playlist_id: s.currentPlaylistId,
          status: s.status,
          last_seen: new Date(s.lastSeen).toISOString()
        })),
        { onConflict: 'id' }
      );
      if (screensError) throw screensError;
    }
  } catch (e) {
    console.error('❌ Erro na Sincronização Cloud:', e);
    throw e;
  }
};

export const deleteMediaFromCloud = async (mediaId: string) => {
  await supabase.from('adcast_playlist_items').delete().eq('media_id', mediaId);
  const { error } = await supabase.from('adcast_media').delete().eq('id', mediaId);
  if (error) throw error;
};

export const deletePlaylistFromCloud = async (playlistId: string) => {
  await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlistId);
  const { error } = await supabase.from('adcast_playlists').delete().eq('id', playlistId);
  if (error) throw error;
};

export const deleteScreenFromCloud = async (screenId: string) => {
  const { error } = await supabase.from('adcast_screens').delete().eq('id', screenId);
  if (error) throw error;
};

export const createNewProject = async (): Promise<string | null> => {
  const projectId = `prj-${Math.random().toString(36).substr(2, 9)}`;
  try {
    const { error: mError } = await supabase.from('adcast_media').insert(
      INITIAL_MEDIA.map(m => ({ 
        id: m.id, 
        name: m.name, 
        url: m.url, 
        type: m.type, 
        duration: m.duration, 
        project_id: projectId 
      }))
    );
    if (mError) throw mError;

    const { error: pError } = await supabase.from('adcast_playlists').insert(
      INITIAL_PLAYLISTS.map(p => ({ id: p.id, name: p.name, project_id: projectId }))
    );
    if (pError) throw pError;

    for (const p of INITIAL_PLAYLISTS) {
      const { error: piError } = await supabase.from('adcast_playlist_items').insert(
        p.items.map((mid, idx) => ({ playlist_id: p.id, media_id: mid, position: idx }))
      );
      if (piError) throw piError;
    }
    return projectId;
  } catch (e) {
    console.error('Erro ao criar projeto:', e);
    return null;
  }
};

export const updateScreenHeartbeat = async (screenId: string, syncId?: string, screenName?: string) => {
  if (!syncId) return;
  try {
    // Tenta primeiro atualizar apenas status e data, para não sobrescrever o nome existente
    const { data, error } = await supabase
      .from('adcast_screens')
      .update({ 
        last_seen: new Date().toISOString(),
        status: 'online',
        ...(screenName ? { name: screenName } : {})
      })
      .eq('id', screenId)
      .select();

    // Se não atualizou nada (não existe no banco), então insere pela primeira vez
    if (!error && (!data || data.length === 0)) {
      await supabase.from('adcast_screens').upsert({ 
        id: screenId,
        project_id: syncId,
        name: screenName || 'Nova Tela',
        last_seen: new Date().toISOString(),
        status: 'online'
      }, { onConflict: 'id' });
    }
  } catch (e) {
    console.warn('⚠️ Falha no Heartbeat:', e);
  }
};

export const subscribeToProjectChanges = (syncId: string, callback: () => void) => {
  return supabase
    .channel(`project-realtime-${syncId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_media' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlists' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlist_items' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_screens' }, callback)
    .subscribe();
};

export const getLiveScreensStatus = async (syncId: string) => {
  try {
    const { data, error } = await supabase
      .from('adcast_screens')
      .select('id, last_seen')
      .eq('project_id', syncId);
    if (error) throw error;
    return data?.map(s => ({ screen_id: s.id, last_seen: s.last_seen })) || [];
  } catch (e) {
    return [];
  }
};

export const checkSupabaseHealth = async () => {
  try {
    const results = await Promise.all([
      supabase.from('adcast_media').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlists').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlist_items').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_screens').select('count', { count: 'exact', head: true })
    ]);
    const tables = {
      'Mídias': !results[0].error,
      'Playlists': !results[1].error,
      'Itens': !results[2].error,
      'Telas': !results[3].error
    };
    return { connected: Object.values(tables).every(s => s === true), tables };
  } catch (e) {
    return { connected: false, tables: {} };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { AppState, MediaItem } from '../types';
import { getActiveProjectId, updateScreenHeartbeat, loadRemoteState, subscribeToProjectChanges } from '../services/storage';
import { Loader2, AlertCircle, Monitor, Wifi, Code2, Maximize2, RotateCcw, Download } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [showControls, setShowControls] = useState(true);
  const [installPrompt, setInstallPrompt] = useState<any>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const playerRef = useRef<HTMLDivElement>(null);

  const fetchData = async () => {
    const params = new URLSearchParams(window.location.search);
    const urlSyncId = params.get('sync');
    const savedSyncId = getActiveProjectId();
    const targetId = urlSyncId || savedSyncId;

    if (targetId) {
      const remoteState = await loadRemoteState(targetId);
      if (remoteState) {
        setState(remoteState);
        const currentScreen = remoteState.screens.find(s => s.id === screenId);
        updateScreenHeartbeat(screenId, targetId, currentScreen?.name);
      } else {
        updateScreenHeartbeat(screenId, targetId);
      }
    }
    setLoading(false);
  };

  // Captura o evento de instalação do navegador
  useEffect(() => {
    const handler = (e: any) => {
      e.preventDefault();
      setInstallPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  // Efeito para gerar o PWA único para esta tela
  useEffect(() => {
    const screen = state?.screens.find(s => s.id === screenId);
    if (screen) {
      const screenName = screen.name || `Tela ${screenId}`;
      const manifest = {
        id: `adcast-player-${screenId}`, // ID exclusivo para diferenciar os PWAs no mesmo domínio
        name: `AdCast: ${screenName}`,
        short_name: screenName,
        description: `Player exclusivo para a tela ${screenName}`,
        start_url: window.location.href, // Abre exatamente nesta URL
        display: "fullscreen",
        background_color: "#000000",
        theme_color: "#000000",
        orientation: "any",
        icons: [
          {
            src: "https://cdn-icons-png.flaticon.com/512/3596/3596091.png",
            sizes: "512x512",
            type: "image/png",
            purpose: "any maskable"
          }
        ]
      };

      const stringManifest = JSON.stringify(manifest);
      const blob = new Blob([stringManifest], { type: 'application/json' });
      const manifestURL = URL.createObjectURL(blob);

      const manifestTag = document.getElementById('dynamic-manifest');
      if (manifestTag) {
        manifestTag.setAttribute('href', manifestURL);
      }

      document.title = `${screenName} | Player`;
    }
  }, [state, screenId]);

  const handleInstall = async () => {
    if (!installPrompt) return;
    installPrompt.prompt();
    const { outcome } = await installPrompt.userChoice;
    if (outcome === 'accepted') {
      setInstallPrompt(null);
    }
  };

  const enterFullscreen = async () => {
    try {
      if (!document.fullscreenElement) {
        await playerRef.current?.requestFullscreen();
      }
    } catch (err) {
      console.warn('Fullscreen automático bloqueado.');
    }
    setShowControls(false);
  };

  useEffect(() => {
    fetchData();
    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    let subscription: any = null;
    if (syncId) {
      subscription = subscribeToProjectChanges(syncId, async () => {
        const updated = await loadRemoteState(syncId);
        if (updated) setState(updated);
      });
    }

    const heartbeatInterval = setInterval(() => {
      const currentSyncId = syncId || getActiveProjectId() || state?.syncId;
      if (currentSyncId) {
        const currentScreenName = state?.screens.find(s => s.id === screenId)?.name;
        updateScreenHeartbeat(screenId, currentSyncId, currentScreenName);
      }
    }, 30000);

    const controlTimer = setTimeout(() => setShowControls(false), 5000);

    return () => {
      if (subscription) subscription.unsubscribe();
      clearInterval(heartbeatInterval);
      clearTimeout(controlTimer);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId, state?.syncId, state?.screens]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight text-white">Carregando Terminal...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <h2 className="text-3xl font-bold text-white">Terminal não Registrado</h2>
        <p className="text-lg text-slate-500 max-w-md">ID: <span className="text-rose-400 font-mono">{screenId}</span></p>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white">Reconectar</button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center" onClick={() => setShowControls(true)}>
        <Monitor size={100} className="mb-8 opacity-10" />
        <h2 className="text-3xl font-black text-white uppercase mb-2">Sem Programação</h2>
        <p className="mb-8 text-slate-400">{screen.name}</p>

        {/* Botão de Instalação Visível quando não há conteúdo */}
        {installPrompt && (
          <button 
            onClick={handleInstall}
            className="flex items-center gap-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold transition-all animate-bounce"
          >
            <Download size={20} /> Instalar como App na TV
          </button>
        )}
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  return (
    <div 
      ref={playerRef}
      className="h-screen w-screen bg-black overflow-hidden relative select-none touch-none"
      onClick={() => setShowControls(!showControls)}
    >
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in duration-1000"
            key={activeItem.id}
          />
        ) : activeItem.type === 'video' ? (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={() => setCurrentIndex((prev) => (prev + 1) % currentItems.length)}
          />
        ) : (
          <div 
            className="w-full h-full flex items-center justify-center bg-white"
            dangerouslySetInnerHTML={{ __html: activeItem.url }}
            key={activeItem.id}
          />
        )}
      </div>

      {/* Controles do Player */}
      <div className={`absolute top-8 right-8 z-50 flex gap-2 transition-all duration-500 ${showControls ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4 pointer-events-none'}`}>
        {installPrompt && (
          <button 
            onClick={(e) => { e.stopPropagation(); handleInstall(); }}
            className="flex items-center gap-2 px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 backdrop-blur-md rounded-full text-white border border-indigo-400/30 font-bold text-xs shadow-xl"
          >
            <Download size={18} /> Instalar App
          </button>
        )}
        <button 
          onClick={(e) => { e.stopPropagation(); enterFullscreen(); }}
          className="p-3 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full text-white border border-white/20"
        >
          <Maximize2 size={24} />
        </button>
        <button 
          onClick={(e) => { e.stopPropagation(); window.location.reload(); }}
          className="p-3 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full text-white border border-white/20"
        >
          <RotateCcw size={24} />
        </button>
      </div>

      <div className={`absolute bottom-8 left-8 z-50 flex items-center gap-3 bg-black/30 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
        <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.8)]" />
        <span className="text-white text-xs font-black uppercase tracking-widest">{screen.name}</span>
      </div>

      <div className="absolute bottom-0 left-0 h-1 bg-indigo-500/30 w-full z-50">
        <div 
          className="h-full bg-indigo-500"
          style={{ 
            width: '100%',
            animation: `progress ${(activeItem.duration || 10)}s linear infinite` 
          }}
          key={`${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
        .w-full iframe { width: 100% !important; height: 100% !important; border: none; }
      `}</style>
    </div>
  );
};

