export const createNewProject = async (): Promise<string | null> => {
  const projectId = `prj-${Math.random().toString(36).substr(2, 9)}`;
  try {
    await supabase.from('adcast_media').insert(
      INITIAL_MEDIA.map(m => ({ ...m, project_id: projectId }))
    );
    await supabase.from('adcast_playlists').insert(
      INITIAL_PLAYLISTS.map(p => ({ id: p.id, name: p.name, project_id: projectId }))
    );
    for (const p of INITIAL_PLAYLISTS) {
      await supabase.from('adcast_playlist_items').insert(
        p.items.map((mid, idx) => ({ playlist_id: p.id, media_id: mid, position: idx }))
      );
    }
    return projectId;
  } catch (e) {
    return null;
  }
};

export const updateScreenHeartbeat = async (screenId: string, syncId?: string, screenName?: string) => {
  if (!syncId) return;
  try {
    // Primeiro tentamos um UPDATE para não sobrescrever o nome se ele já existir
    const { data, error } = await supabase
      .from('adcast_screens')
      .update({ 
        last_seen: new Date().toISOString(),
        status: 'online',
        ...(screenName ? { name: screenName } : {}) // Só atualiza nome se ele for passado explicitamente
      })
      .eq('id', screenId)
      .select();

    // Se o registro não existe (não atualizou nada), então fazemos o insert inicial
    if (!error && (!data || data.length === 0)) {
      await supabase.from('adcast_screens').insert({ 
        id: screenId,
        project_id: syncId,
        name: screenName || 'Terminal de Exibição',
        last_seen: new Date().toISOString(),
        status: 'online'
      });
    }
  } catch (e) {
    console.warn('⚠️ Falha no Heartbeat:', e);
  }
};

export const subscribeToProjectChanges = (syncId: string, callback: () => void) => {
  return supabase
    .channel(`project-realtime-${syncId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_media' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlists' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlist_items' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_screens' }, callback)
    .subscribe();
};

export const getLiveScreensStatus = async (syncId: string) => {
  try {
    const { data, error } = await supabase
      .from('adcast_screens')
      .select('id, last_seen')
      .eq('project_id', syncId);
    if (error) throw error;
    return data?.map(s => ({ screen_id: s.id, last_seen: s.last_seen })) || [];
  } catch (e) {
    return [];
  }
};

export const checkSupabaseHealth = async () => {
  try {
    const results = await Promise.all([
      supabase.from('adcast_media').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlists').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlist_items').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_screens').select('count', { count: 'exact', head: true })
    ]);
    const tables = {
      'Mídias': !results[0].error,
      'Playlists': !results[1].error,
      'Itens': !results[2].error,
      'Telas': !results[3].error
    };
    return { connected: Object.values(tables).every(s => s === true), tables };
  } catch (e) {
    return { connected: false, tables: {} };
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { AppState, MediaItem } from '../types';
import { getActiveProjectId, updateScreenHeartbeat, loadRemoteState, subscribeToProjectChanges } from '../services/storage';
import { Loader2, AlertCircle, Monitor, Wifi, Code2, RotateCcw, Maximize2 } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [showControls, setShowControls] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const playerRef = useRef<HTMLDivElement>(null);

  const fetchData = async () => {
    const params = new URLSearchParams(window.location.search);
    const urlSyncId = params.get('sync');
    const savedSyncId = getActiveProjectId();
    const targetId = urlSyncId || savedSyncId;

    if (targetId) {
      const remoteState = await loadRemoteState(targetId);
      if (remoteState) {
        setState(remoteState);
        const currentScreen = remoteState.screens.find(s => s.id === screenId);
        // Passa o nome existente para o heartbeat
        updateScreenHeartbeat(screenId, targetId, currentScreen?.name);
      } else {
        updateScreenHeartbeat(screenId, targetId);
      }
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    let subscription: any = null;
    if (syncId) {
      subscription = subscribeToProjectChanges(syncId, async () => {
        const updated = await loadRemoteState(syncId);
        if (updated) setState(updated);
      });
    }

    const heartbeatInterval = setInterval(() => {
      const currentSyncId = syncId || getActiveProjectId() || state?.syncId;
      if (currentSyncId) {
        const currentScreenName = state?.screens.find(s => s.id === screenId)?.name;
        updateScreenHeartbeat(screenId, currentSyncId, currentScreenName);
      }
    }, 30000);

    return () => {
      if (subscription) subscription.unsubscribe();
      clearInterval(heartbeatInterval);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId, state?.syncId, state?.screens]);

  const screen = state?.screens.find(s => s.id === screenId);
  const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
  const currentItems = playlist?.items.map(id => state?.library.find(item => item.id === id)).filter(Boolean) as MediaItem[] || [];

  useEffect(() => {
    if (currentItems.length > 0) {
      const currentItem = currentItems[currentIndex];
      if (timerRef.current) clearTimeout(timerRef.current);

      timerRef.current = setTimeout(() => {
        setCurrentIndex((prev) => (prev + 1) % currentItems.length);
      }, (currentItem?.duration || 10) * 1000);
    }
  }, [currentIndex, currentItems.length]);

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      playerRef.current?.requestFullscreen().catch(err => {
        console.warn(`Erro ao entrar em tela cheia: ${err.message}`);
      });
    } else {
      document.exitFullscreen();
    }
  };

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight">Sincronizando Terminal Cloud...</p>
      </div>
    );
  }

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <h2 className="text-3xl font-bold text-white">Terminal não Registrado</h2>
        <p className="text-lg text-slate-500 max-w-md">ID: <span className="text-rose-400 font-mono">{screenId}</span></p>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white">
          Tentar Reconectar
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div 
        className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center relative"
        onMouseMove={() => setShowControls(true)}
      >
        <Monitor size={100} className="mb-8 opacity-10" />
        <h2 className="text-3xl font-black text-white uppercase mb-2">Sem Programação Cloud</h2>
        <p className="mb-8 text-slate-400">{screen.name}</p>
        <div className="flex items-center gap-2 px-4 py-2 bg-slate-950 rounded-full border border-slate-800 text-xs text-emerald-500">
          <Wifi size={14} /> Conectado ao Workspace
        </div>

        <div className={`absolute top-4 right-4 flex gap-2 transition-opacity duration-300 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
           <button onClick={() => window.location.reload()} className="p-2 bg-slate-800 text-white rounded-lg hover:bg-slate-700">
             <RotateCcw size={20} />
           </button>
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  return (
    <div 
      ref={playerRef}
      className="h-screen w-screen bg-black overflow-hidden relative select-none cursor-none group"
      onMouseMove={() => {
        setShowControls(true);
        setTimeout(() => setShowControls(false), 3000);
      }}
    >
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000"
            key={activeItem.id}
          />
        ) : activeItem.type === 'video' ? (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={() => setCurrentIndex((prev) => (prev + 1) % currentItems.length)}
          />
        ) : (
          <div 
            className="w-full h-full flex items-center justify-center bg-white"
            dangerouslySetInnerHTML={{ __html: activeItem.url }}
            key={activeItem.id}
          />
        )}
      </div>

      {/* Interface Ocultável do Player */}
      <div className={`absolute top-0 inset-x-0 p-6 flex justify-between items-start z-50 transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
        <div className="flex items-center gap-3 bg-black/40 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full">
          <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.8)]" />
          <span className="text-white text-xs font-black uppercase tracking-widest">{screen.name}</span>
          {activeItem.type === 'html' && <Code2 size={12} className="text-indigo-400" />}
        </div>

        <div className="flex gap-2">
          <button 
            onClick={toggleFullscreen}
            className="p-3 bg-black/40 backdrop-blur-md text-white rounded-full border border-white/10 hover:bg-white/20 transition-all"
          >
            <Maximize2 size={20} />
          </button>
          <button 
            onClick={() => window.location.reload()}
            className="p-3 bg-black/40 backdrop-blur-md text-white rounded-full border border-white/10 hover:bg-white/20 transition-all"
          >
            <RotateCcw size={20} />
          </button>
        </div>
      </div>

      <div className="absolute bottom-0 left-0 h-1 bg-indigo-500/30 w-full z-50">
        <div 
          className="h-full bg-indigo-500"
          style={{ 
            width: '100%',
            animation: `progress ${(activeItem.duration || 10)}s linear infinite` 
          }}
          key={`${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes progress {
          from { width: 0%; }
          to { width: 100%; }
        }
        .group:hover { cursor: default; }
        .w-full iframe { max-width: 100%; height: 100%; width: 100%; border: none; }
      `}</style>
    </div>
  );
};

-- ==========================================
-- ADCAST CLOUD - SETUP DE BANCO DE DADOS
-- ==========================================

-- PARTE 1: LIMPEZA (OPCIONAL)
-- DROP TABLE IF EXISTS adcast_playlist_items CASCADE;
-- DROP TABLE IF EXISTS adcast_screens CASCADE;
-- DROP TABLE IF EXISTS adcast_playlists CASCADE;
-- DROP TABLE IF EXISTS adcast_media CASCADE;

-- PARTE 2: CRIAÇÃO

-- Tabela de Mídias (Imagens, Vídeos e Widgets)
CREATE TABLE IF NOT EXISTS adcast_media (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  url TEXT NOT NULL,
  type TEXT NOT NULL,
  duration INTEGER NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Tabela de Playlists
CREATE TABLE IF NOT EXISTS adcast_playlists (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- Itens de Playlist (Define a ordem das mídias)
CREATE TABLE IF NOT EXISTS adcast_playlist_items (
  id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  playlist_id TEXT REFERENCES adcast_playlists(id) ON DELETE CASCADE,
  media_id TEXT REFERENCES adcast_media(id) ON DELETE CASCADE,
  position INTEGER NOT NULL
);

-- Telas / Terminais
CREATE TABLE IF NOT EXISTS adcast_screens (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  current_playlist_id TEXT REFERENCES adcast_playlists(id) ON DELETE SET NULL,
  status TEXT NOT NULL,
  last_seen TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- PARTE 3: REALTIME
-- Nota: Se a publicação 'supabase_realtime' já existir, use ALTER PUBLICATION
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    CREATE PUBLICATION supabase_realtime;
  END IF;

  ALTER PUBLICATION supabase_realtime ADD TABLE adcast_media;
  ALTER PUBLICATION supabase_realtime ADD TABLE adcast_playlists;
  ALTER PUBLICATION supabase_realtime ADD TABLE adcast_playlist_items;
  ALTER PUBLICATION supabase_realtime ADD TABLE adcast_screens;
EXCEPTION
  WHEN others THEN 
    RAISE NOTICE 'A publicação já continha algumas tabelas ou falhou. Verifique manualmente em Database > Replication.';
END $$;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { AppState, MediaItem } from '../types';
import { getActiveProjectId, updateScreenHeartbeat, loadRemoteState, subscribeToProjectChanges } from '../services/storage';
import { Loader2, AlertCircle, Monitor, Wifi, Code2, RotateCcw, Maximize2 } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [showControls, setShowControls] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const playerRef = useRef<HTMLDivElement>(null);

  const fetchData = async () => {
    const params = new URLSearchParams(window.location.search);
    const urlSyncId = params.get('sync');
    const savedSyncId = getActiveProjectId();
    const targetId = urlSyncId || savedSyncId;

    if (targetId) {
      const remoteState = await loadRemoteState(targetId);
      if (remoteState) {
        setState(remoteState);
        const currentScreen = remoteState.screens.find(s => s.id === screenId);
        updateScreenHeartbeat(screenId, targetId, currentScreen?.name);
      } else {
        updateScreenHeartbeat(screenId, targetId);
      }
    }
    setLoading(false);
  };

  // Carregamento inicial e Realtime
  useEffect(() => {
    fetchData();
    const params = new URLSearchParams(window.location.search);
    const syncId = params.get('sync');

    let subscription: any = null;
    if (syncId) {
      subscription = subscribeToProjectChanges(syncId, async () => {
        const updated = await loadRemoteState(syncId);
        if (updated) setState(updated);
      });
    }

    // Heartbeat a cada 30 segundos
    const heartbeatInterval = setInterval(() => {
      const currentSyncId = syncId || getActiveProjectId() || state?.syncId;
      if (currentSyncId) {
        const currentScreenName = state?.screens.find(s => s.id === screenId)?.name;
        updateScreenHeartbeat(screenId, currentSyncId, currentScreenName);
      }
    }, 30000);

    return () => {
      if (subscription) subscription.unsubscribe();
      clearInterval(heartbeatInterval);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId]); // Removidas dependências que causavam re-execução excessiva

  // Memoizar a lista de itens para evitar disparos do useEffect do timer quando o estado muda mas a playlist é a mesma
  const currentItems = useMemo(() => {
    const screen = state?.screens.find(s => s.id === screenId);
    const playlist = state?.playlists.find(p => p.id === screen?.currentPlaylistId);
    return playlist?.items
      .map(id => state?.library.find(item => item.id === id))
      .filter(Boolean) as MediaItem[] || [];
  }, [state, screenId]);

  // Garantir que o currentIndex não fique fora dos limites se a playlist diminuir
  useEffect(() => {
    if (currentIndex >= currentItems.length && currentItems.length > 0) {
      setCurrentIndex(0);
    }
  }, [currentItems.length, currentIndex]);

  // Lógica de transição automática (Timer para Imagem/HTML)
  useEffect(() => {
    if (currentItems.length > 1) {
      const activeItem = currentItems[currentIndex];
      if (!activeItem) return;

      // Limpa qualquer timer anterior
      if (timerRef.current) clearTimeout(timerRef.current);

      // Só usamos timer se NÃO for vídeo (vídeos usam onEnded)
      if (activeItem.type !== 'video') {
        const duration = (activeItem.duration || 10) * 1000;
        timerRef.current = setTimeout(() => {
          setCurrentIndex((prev) => (prev + 1) % currentItems.length);
        }, duration);
      }
    } else {
      // Se tiver 1 ou 0 itens, limpa timers
      if (timerRef.current) clearTimeout(timerRef.current);
    }

    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [currentIndex, currentItems]); // Só dispara se o índice ou a lista memoizada mudar

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      playerRef.current?.requestFullscreen().catch(err => {
        console.warn(`Erro ao entrar em tela cheia: ${err.message}`);
      });
    } else {
      document.exitFullscreen();
    }
  };

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight">Sincronizando Terminal Cloud...</p>
      </div>
    );
  }

  const screen = state?.screens.find(s => s.id === screenId);

  if (!screen) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-6 p-10 text-center">
        <AlertCircle className="text-rose-500" size={64} />
        <h2 className="text-3xl font-bold text-white">Terminal não Registrado</h2>
        <p className="text-lg text-slate-500 max-w-md">ID: <span className="text-rose-400 font-mono">{screenId}</span></p>
        <button onClick={() => window.location.reload()} className="px-6 py-3 bg-slate-800 rounded-xl text-white">
          Tentar Reconectar
        </button>
      </div>
    );
  }

  if (currentItems.length === 0) {
    return (
      <div 
        className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center relative"
        onMouseMove={() => setShowControls(true)}
      >
        <Monitor size={100} className="mb-8 opacity-10" />
        <h2 className="text-3xl font-black text-white uppercase mb-2">Sem Programação Cloud</h2>
        <p className="mb-8 text-slate-400">{screen.name}</p>
        <div className="flex items-center gap-2 px-4 py-2 bg-slate-950 rounded-full border border-slate-800 text-xs text-emerald-500">
          <Wifi size={14} /> Conectado ao Workspace
        </div>

        <div className={`absolute top-4 right-4 flex gap-2 transition-opacity duration-300 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
           <button onClick={() => window.location.reload()} className="p-2 bg-slate-800 text-white rounded-lg hover:bg-slate-700">
             <RotateCcw size={20} />
           </button>
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];

  const handleMediaEnd = () => {
    setCurrentIndex((prev) => (prev + 1) % currentItems.length);
  };

  return (
    <div 
      ref={playerRef}
      className="h-screen w-screen bg-black overflow-hidden relative select-none cursor-none group"
      onMouseMove={() => {
        setShowControls(true);
        setTimeout(() => setShowControls(false), 3000);
      }}
    >
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000"
            key={`img-${activeItem.id}-${currentIndex}`}
          />
        ) : activeItem.type === 'video' ? (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={handleMediaEnd}
            key={`vid-${activeItem.id}-${currentIndex}`}
          />
        ) : (
          <div 
            className="w-full h-full flex items-center justify-center bg-white"
            dangerouslySetInnerHTML={{ __html: activeItem.url }}
            key={`html-${activeItem.id}-${currentIndex}`}
          />
        )}
      </div>

      {/* Interface Ocultável do Player */}
      <div className={`absolute top-0 inset-x-0 p-6 flex justify-between items-start z-50 transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
        <div className="flex items-center gap-3 bg-black/40 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full">
          <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.8)]" />
          <span className="text-white text-xs font-black uppercase tracking-widest">{screen.name}</span>
          {activeItem.type === 'html' && <Code2 size={12} className="text-indigo-400" />}
        </div>

        <div className="flex gap-2">
          <button 
            onClick={toggleFullscreen}
            className="p-3 bg-black/40 backdrop-blur-md text-white rounded-full border border-white/10 hover:bg-white/20 transition-all"
          >
            <Maximize2 size={20} />
          </button>
          <button 
            onClick={() => window.location.reload()}
            className="p-3 bg-black/40 backdrop-blur-md text-white rounded-full border border-white/10 hover:bg-white/20 transition-all"
          >
            <RotateCcw size={20} />
          </button>
        </div>
      </div>

      {/* Barra de Progresso Sincronizada */}
      <div className="absolute bottom-0 left-0 h-1 bg-indigo-500/20 w-full z-50">
        <div 
          className="h-full bg-indigo-500"
          style={{ 
            animation: activeItem.type !== 'video' 
              ? `player-progress ${(activeItem.duration || 10)}s linear forwards` 
              : 'none' 
          }}
          key={`progress-${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes player-progress {
          from { width: 0%; }
          to { width: 100%; }
        }
        .group:hover { cursor: default; }
        .w-full iframe { max-width: 100%; height: 100%; width: 100%; border: none; }
      `}</style>
    </div>
  );
};

