import React, { useState, useEffect, useRef, useMemo } from 'react';
import { AppState, MediaItem } from '../types';
import { getActiveProjectId, updateScreenHeartbeat, loadRemoteState, subscribeToProjectChanges } from '../services/storage';
import { Loader2, AlertCircle, Monitor, Wifi, Code2, RotateCcw, Maximize2 } from 'lucide-react';

interface PlayerProps {
  screenId: string;
}

const SafeHTML = React.memo(({ html }: { html: string }) => {
  return (
    <div 
      className="w-full h-full flex items-center justify-center bg-white"
      dangerouslySetInnerHTML={useMemo(() => ({ __html: html }), [html])}
    />
  );
});

export const Player: React.FC<PlayerProps> = ({ screenId }) => {
  const [state, setState] = useState<AppState | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [showControls, setShowControls] = useState(false);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const playerRef = useRef<HTMLDivElement>(null);

  const fetchData = async (syncId: string) => {
    console.log(`[Player] Buscando dados remotos para o projeto: ${syncId}`);
    const remoteState = await loadRemoteState(syncId);
    if (remoteState) {
      setState(remoteState);
      const currentScreen = remoteState.screens.find(s => s.id === screenId);
      updateScreenHeartbeat(screenId, syncId, currentScreen?.name);
    }
  };

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const urlSyncId = params.get('sync');
    const savedSyncId = getActiveProjectId();
    const targetSyncId = urlSyncId || savedSyncId;

    if (!targetSyncId) {
      console.warn("[Player] Nenhum SyncID encontrado na URL ou Storage.");
      setLoading(false);
      return;
    }

    fetchData(targetSyncId).then(() => setLoading(false));

    const subscription = subscribeToProjectChanges(targetSyncId, async (payload) => {
      // REGRA DE FILTRAGEM:
      // Se a mudança for na tabela de telas, só recarregamos se for a NOSSA tela
      // e se algo ALÉM do tempo de heartbeat mudou (ex: playlist ou a refresh_key)
      if (payload.table === 'adcast_screens') {
        const isSelf = payload.new.id === screenId;
        const playlistChanged = payload.new.current_playlist_id !== payload.old?.current_playlist_id;
        const refreshTriggered = payload.new.refresh_key !== payload.old?.refresh_key;

        if (isSelf && (playlistChanged || refreshTriggered)) {
          console.log("[REALTIME] Comando de atualização ou nova playlist detectada!");
          const updated = await loadRemoteState(targetSyncId);
          if (updated) setState(updated);
        }
        return; // Ignora se for apenas heartbeat
      }

      // Para outras tabelas (mídia, playlists), recarrega sempre
      console.log(`[REALTIME] Mudança global em ${payload.table}. Sincronizando...`);
      const updated = await loadRemoteState(targetSyncId);
      if (updated) setState(updated);
    });

    const heartbeatInterval = setInterval(() => {
      const currentScreenName = state?.screens.find(s => s.id === screenId)?.name;
      updateScreenHeartbeat(screenId, targetSyncId, currentScreenName);
    }, 30000);

    return () => {
      if (subscription) subscription.unsubscribe();
      clearInterval(heartbeatInterval);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId]);

  const currentItems = useMemo(() => {
    const screen = state?.screens.find(s => s.id === screenId);
    if (!screen || !screen.currentPlaylistId) return [];

    const playlist = state?.playlists.find(p => p.id === screen.currentPlaylistId);
    if (!playlist) return [];

    return playlist.items
      .map(id => state?.library.find(item => item.id === id))
      .filter(Boolean) as MediaItem[];
  }, [state, screenId]);

  useEffect(() => {
    if (currentItems.length > 0 && currentIndex >= currentItems.length) {
      setCurrentIndex(0);
    }
  }, [currentItems, currentIndex]);

  useEffect(() => {
    if (currentItems.length > 0) {
      const activeItem = currentItems[currentIndex];
      if (!activeItem) return;

      if (timerRef.current) clearTimeout(timerRef.current);

      if (activeItem.type !== 'video') {
        const duration = (activeItem.duration || 10) * 1000;
        timerRef.current = setTimeout(() => {
          setCurrentIndex((prev) => (prev + 1) % currentItems.length);
        }, duration);
      }
    }
    return () => { if (timerRef.current) clearTimeout(timerRef.current); };
  }, [currentIndex, currentItems]);

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      playerRef.current?.requestFullscreen().catch(err => console.warn(err));
    } else {
      document.exitFullscreen();
    }
  };

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight">Sincronizando com AdCast Cloud...</p>
      </div>
    );
  }

  const screen = state?.screens.find(s => s.id === screenId);

  if (!screen || currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center relative">
        <Monitor size={100} className="mb-8 opacity-10" />
        <h2 className="text-3xl font-black text-white uppercase mb-2">Aguardando Programação</h2>
        <p className="text-slate-400 mb-6 max-w-md">Esta tela está online sob o ID: <span className="text-indigo-400 font-mono">{screenId}</span>. Selecione uma playlist no painel de controle.</p>
        <div className="flex items-center gap-2 px-4 py-2 bg-slate-950 rounded-full border border-slate-800 text-xs text-emerald-500">
          <Wifi size={14} /> Link Cloud Ativo
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];
  const handleMediaEnd = () => setCurrentIndex((prev) => (prev + 1) % currentItems.length);

  return (
    <div 
      ref={playerRef}
      className="h-screen w-screen bg-black overflow-hidden relative select-none cursor-none group"
      onMouseMove={() => {
        setShowControls(true);
        setTimeout(() => setShowControls(false), 3000);
      }}
    >
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in duration-1000"
            key={activeItem.id} 
          />
        ) : activeItem.type === 'video' ? (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={handleMediaEnd}
            key={activeItem.id}
          />
        ) : (
          <SafeHTML html={activeItem.url} key={activeItem.id} />
        )}
      </div>

      <div className={`absolute top-0 inset-x-0 p-6 flex justify-between items-start z-50 transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
        <div className="flex items-center gap-3 bg-black/40 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full">
          <div className="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse" />
          <span className="text-white text-xs font-black uppercase tracking-widest">{screen.name}</span>
        </div>
        <div className="flex gap-2">
          <button onClick={toggleFullscreen} className="p-3 bg-black/40 backdrop-blur-md text-white rounded-full border border-white/10 hover:bg-white/10 transition-colors">
            <Maximize2 size={20} />
          </button>
          <button onClick={() => window.location.reload()} className="p-3 bg-black/40 backdrop-blur-md text-white rounded-full border border-white/10 hover:bg-white/10 transition-colors">
            <RotateCcw size={20} />
          </button>
        </div>
      </div>

      <div className="absolute bottom-0 left-0 h-1 bg-indigo-500/10 w-full z-50">
        <div 
          className="h-full bg-indigo-500/60 transition-all duration-300"
          style={{ 
            animation: activeItem.type !== 'video' 
              ? `player-progress ${(activeItem.duration || 10)}s linear forwards` 
              : 'none' 
          }}
          key={`progress-${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes player-progress { from { width: 0%; } to { width: 100%; } }
        .w-full iframe { width: 100vw; height: 100vh; border: none; position: fixed; top: 0; left: 0; }
      `}</style>
    </div>
  );
};

