      setIsOnline(true);
      fetchData(targetSyncId);
      setupSubscription();
    };
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    // Watchdog e Heartbeat (Executa a cada 30s)
    const interval = setInterval(() => {
      updateScreenHeartbeat(screenId, targetSyncId);

      // Se não sincronizou nos últimos 10 minutos (segurança extra), força uma
      if (Date.now() - lastSyncRef.current > 600000) {
        fetchData(targetSyncId);
      }
    }, 30000);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
      if (subscriptionRef.current) subscriptionRef.current.unsubscribe();
      clearInterval(interval);
      if (timerRef.current) clearTimeout(timerRef.current);
    };
  }, [screenId]); // Importante: removido lastSync das dependências

  const currentItems = useMemo(() => {
    const screen = state?.screens.find(s => s.id === screenId);
    if (!screen || !screen.currentPlaylistId) return [];

    const playlist = state?.playlists.find(p => p.id === screen.currentPlaylistId);
    if (!playlist) return [];

    return playlist.items
      .map(id => state?.library.find(item => item.id === id))
      .filter(Boolean) as MediaItem[];
  }, [state, screenId]);

  // Lógica do Carrossel (Avanço de Mídia)
  useEffect(() => {
    if (currentItems.length > 0) {
      const activeItem = currentItems[currentIndex];
      if (!activeItem) {
        setCurrentIndex(0);
        return;
      }

      if (timerRef.current) clearTimeout(timerRef.current);

      if (activeItem.type !== 'video') {
        const duration = (activeItem.duration || 10) * 1000;
        timerRef.current = setTimeout(() => {
          setCurrentIndex((prev) => (prev + 1) % currentItems.length);
        }, duration);
      }
    }
  }, [currentIndex, currentItems]);

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      playerRef.current?.requestFullscreen().catch(err => console.warn(err));
    } else {
      document.exitFullscreen();
    }
  };

  if (loading) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-950 text-slate-400 gap-4">
        <Loader2 className="animate-spin text-indigo-500" size={48} />
        <p className="text-xl font-medium tracking-tight">Carregando Programação...</p>
      </div>
    );
  }

  const screen = state?.screens.find(s => s.id === screenId);

  if (!screen || currentItems.length === 0) {
    return (
      <div className="h-screen w-screen flex flex-col items-center justify-center bg-slate-900 text-slate-500 p-10 text-center relative">
        <Monitor size={100} className="mb-8 opacity-10" />
        <h2 className="text-3xl font-black text-white uppercase mb-2">Sem Programação</h2>
        <p className="text-slate-400 mb-6 max-w-md italic font-mono">ID: {screenId}</p>
        <div className={`flex items-center gap-2 px-4 py-2 rounded-full border text-xs ${isOnline ? 'bg-slate-950 border-slate-800 text-emerald-500' : 'bg-rose-500/10 border-rose-500/20 text-rose-500'}`}>
          {isOnline ? <Wifi size={14} /> : <WifiOff size={14} />}
          {isOnline ? 'Conectado à Nuvem' : 'Tentando Reconectar...'}
        </div>
      </div>
    );
  }

  const activeItem = currentItems[currentIndex];
  const handleMediaEnd = () => setCurrentIndex((prev) => (prev + 1) % currentItems.length);

  return (
    <div 
      ref={playerRef}
      className="h-screen w-screen bg-black overflow-hidden relative select-none cursor-none group"
      onMouseMove={() => {
        setShowControls(true);
        setTimeout(() => setShowControls(false), 3000);
      }}
    >
      <div className="absolute inset-0 flex items-center justify-center">
        {activeItem.type === 'image' ? (
          <img 
            src={activeItem.url} 
            alt={activeItem.name} 
            className="w-full h-full object-cover animate-in fade-in duration-700"
            key={activeItem.id} 
          />
        ) : activeItem.type === 'video' ? (
          <video 
            src={activeItem.url} 
            autoPlay 
            muted 
            playsInline
            className="w-full h-full object-cover"
            onEnded={handleMediaEnd}
            key={activeItem.id}
          />
        ) : (
          <SafeHTML html={activeItem.url} key={activeItem.id} />
        )}
      </div>

      {!isOnline && (
        <div className="absolute bottom-6 right-6 z-[60] flex items-center gap-3 bg-rose-600 text-white px-4 py-2 rounded-lg shadow-2xl animate-bounce">
          <RefreshCw size={16} className="animate-spin" />
          <span className="text-xs font-bold uppercase tracking-widest">Erro de Rede</span>
        </div>
      )}

      <div className={`absolute top-0 inset-x-0 p-6 flex justify-between items-start z-50 transition-opacity duration-500 ${showControls ? 'opacity-100' : 'opacity-0'}`}>
        <div className="flex items-center gap-3 bg-black/40 backdrop-blur-xl border border-white/10 px-5 py-2.5 rounded-full">
          <div className={`w-2 h-2 rounded-full ${isOnline ? 'bg-emerald-500' : 'bg-rose-500'}`} />
          <span className="text-white text-[10px] font-black uppercase tracking-widest">{screen.name}</span>
        </div>
        <div className="flex gap-2">
          <button onClick={toggleFullscreen} className="p-3 bg-black/40 backdrop-blur-md text-white rounded-full border border-white/10">
            <Maximize2 size={18} />
          </button>
          <button onClick={() => window.location.reload()} className="p-3 bg-black/40 backdrop-blur-md text-white rounded-full border border-white/10">
            <RotateCcw size={18} />
          </button>
        </div>
      </div>

      <div className="absolute bottom-0 left-0 h-1 bg-white/10 w-full z-50">
        <div 
          className="h-full bg-indigo-500 transition-all duration-300 shadow-[0_0_10px_rgba(99,102,241,0.8)]"
          style={{ 
            animation: activeItem.type !== 'video' 
              ? `player-progress ${(activeItem.duration || 10)}s linear forwards` 
              : 'none' 
          }}
          key={`progress-${activeItem.id}-${currentIndex}`}
        />
      </div>

      <style>{`
        @keyframes player-progress { from { width: 0%; } to { width: 100%; } }
        .w-full iframe { width: 100vw; height: 100vh; border: none; position: fixed; top: 0; left: 0; }
      `}</style>
    </div>
  );
};

import { AppState, MediaItem, Playlist, Screen } from '../types';
import { INITIAL_MEDIA, INITIAL_PLAYLISTS, INITIAL_SCREENS } from '../constants';
import { supabase } from './supabase';

const STORAGE_PROJECT_KEY = 'adcast_project_id';

export const getActiveProjectId = (): string | null => {
  return localStorage.getItem(STORAGE_PROJECT_KEY);
};

export const setActiveProjectId = (id: string | null) => {
  if (id) localStorage.setItem(STORAGE_PROJECT_KEY, id);
  else localStorage.removeItem(STORAGE_PROJECT_KEY);
};

export const uploadFile = async (file: File, projectId: string): Promise<string> => {
  const fileExt = file.name.split('.').pop();
  const fileName = `${Math.random().toString(36).substring(2)}.${fileExt}`;
  const filePath = `${projectId}/${fileName}`;

  const { data, error } = await supabase.storage
    .from('media')
    .upload(filePath, file);

  if (error) throw error;

  const { data: { publicUrl } } = supabase.storage
    .from('media')
    .getPublicUrl(filePath);

  return publicUrl;
};

export const loadRemoteState = async (projectId: string): Promise<AppState | null> => {
  try {
    const [mediaRes, playlistRes, screensRes] = await Promise.all([
      supabase.from('adcast_media').select('*').eq('project_id', projectId),
      supabase.from('adcast_playlists').select('*').eq('project_id', projectId),
      supabase.from('adcast_screens').select('*').eq('project_id', projectId)
    ]);

    if (mediaRes.error) throw mediaRes.error;
    if (playlistRes.error) throw playlistRes.error;
    if (screensRes.error) throw screensRes.error;

    const playlistIds = playlistRes.data.map(p => p.id);
    const playlistItemsRes = playlistIds.length > 0 
      ? await supabase.from('adcast_playlist_items').select('*').in('playlist_id', playlistIds)
      : { data: [], error: null };

    if (playlistItemsRes.error) throw playlistItemsRes.error;

    const playlists: Playlist[] = playlistRes.data.map(p => {
      const items = playlistItemsRes.data
        ?.filter(pi => pi.playlist_id === p.id)
        .sort((a, b) => a.position - b.position)
        .map(pi => pi.media_id) || [];

      return { id: p.id, name: p.name, items };
    });

    return {
      syncId: projectId,
      library: mediaRes.data.map(m => ({
        id: m.id,
        name: m.name,
        url: m.url,
        type: m.type as any,
        duration: m.duration,
        createdAt: new Date(m.created_at).getTime()
      })),
      playlists: playlists,
      screens: screensRes.data.map(s => ({
        id: s.id,
        name: s.name,
        currentPlaylistId: s.current_playlist_id,
        status: (Date.now() - new Date(s.last_seen).getTime() < 60000) ? 'online' : 'offline',
        lastSeen: new Date(s.last_seen).getTime()
      }))
    };
  } catch (e) {
    console.error('❌ Erro ao carregar estado remoto:', e);
    return null;
  }
};

export const saveStateToCloud = async (state: AppState) => {
  if (!state.syncId) return;
  try {
    const projectId = state.syncId;

    if (state.library.length > 0) {
      const mediaToUpsert = state.library.map(m => ({
        id: m.id,
        project_id: projectId,
        name: m.name,
        url: m.url,
        type: m.type,
        duration: m.duration
      }));
      await supabase.from('adcast_media').upsert(mediaToUpsert);
    }

    if (state.playlists.length > 0) {
      await supabase.from('adcast_playlists').upsert(
        state.playlists.map(p => ({ id: p.id, project_id: projectId, name: p.name }))
      );

      for (const playlist of state.playlists) {
        await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlist.id);
        if (playlist.items.length > 0) {
          const itemsToInsert = playlist.items.map((mediaId, index) => ({
            playlist_id: playlist.id,
            media_id: mediaId,
            position: index
          }));
          await supabase.from('adcast_playlist_items').insert(itemsToInsert);
        }
      }
    }

    if (state.screens.length > 0) {
      await supabase.from('adcast_screens').upsert(
        state.screens.map(s => ({
          id: s.id,
          project_id: projectId,
          name: s.name,
          current_playlist_id: s.currentPlaylistId,
          status: s.status,
          last_seen: new Date(s.last_seen).toISOString()
        }))
      );
    }
  } catch (e) {
    console.error('❌ Erro na Sincronização Cloud:', e);
    throw e;
  }
};

export const deleteMediaFromCloud = async (mediaId: string) => {
  await supabase.from('adcast_playlist_items').delete().eq('media_id', mediaId);
  const { error } = await supabase.from('adcast_media').delete().eq('id', mediaId);
  if (error) throw error;
};

export const deletePlaylistFromCloud = async (playlistId: string) => {
  await supabase.from('adcast_playlist_items').delete().eq('playlist_id', playlistId);
  const { error } = await supabase.from('adcast_playlists').delete().eq('id', playlistId);
  if (error) throw error;
};

export const deleteScreenFromCloud = async (screenId: string) => {
  const { error } = await supabase.from('adcast_screens').delete().eq('id', screenId);
  if (error) throw error;
};

export const createNewProject = async (): Promise<string | null> => {
  const projectId = `prj-${Math.random().toString(36).substr(2, 9)}`;
  try {
    await supabase.from('adcast_media').insert(
      INITIAL_MEDIA.map(m => ({ ...m, project_id: projectId, created_at: new Date().toISOString() }))
    );
    await supabase.from('adcast_playlists').insert(
      INITIAL_PLAYLISTS.map(p => ({ id: p.id, name: p.name, project_id: projectId }))
    );
    for (const p of INITIAL_PLAYLISTS) {
      await supabase.from('adcast_playlist_items').insert(
        p.items.map((mid, idx) => ({ playlist_id: p.id, media_id: mid, position: idx }))
      );
    }
    return projectId;
  } catch (e) {
    console.error('Erro ao criar projeto:', e);
    return null;
  }
};

export const updateScreenHeartbeat = async (screenId: string, syncId?: string, screenName?: string) => {
  if (!syncId) return;
  try {
    await supabase
      .from('adcast_screens')
      .update({ 
        last_seen: new Date().toISOString(),
        status: 'online'
      })
      .eq('id', screenId);
  } catch (e) {
    console.warn('⚠️ Falha no Heartbeat:', e);
  }
};

export const forceScreenUpdate = async (screenId: string) => {
  const newKey = Math.random().toString(36).substring(7);
  const { error } = await supabase
    .from('adcast_screens')
    .update({ refresh_key: newKey })
    .eq('id', screenId);

  if (error) throw error;
};

export const subscribeToProjectChanges = (syncId: string, callback: (payload: any) => void) => {
  return supabase
    .channel(`project:${syncId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_media' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlists' }, callback)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'adcast_playlist_items' }, callback)
    .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'adcast_screens' }, callback)
    .subscribe();
};

export const getLiveScreensStatus = async (syncId: string) => {
  try {
    const { data, error } = await supabase
      .from('adcast_screens')
      .select('id, last_seen')
      .eq('project_id', syncId);
    if (error) throw error;
    return data?.map(s => ({ screen_id: s.id, last_seen: s.last_seen })) || [];
  } catch (e) {
    return [];
  }
};

export const checkSupabaseHealth = async () => {
  try {
    const results = await Promise.all([
      supabase.from('adcast_media').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlists').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_playlist_items').select('count', { count: 'exact', head: true }),
      supabase.from('adcast_screens').select('count', { count: 'exact', head: true })
    ]);
    const tables = {
      'Mídias': !results[0].error,
      'Playlists': !results[1].error,
      'Itens': !results[2].error,
      'Telas': !results[3].error
    };
    return { connected: Object.values(tables).every(s => s === true), tables };
  } catch (e) {
    return { connected: false, tables: {} };
  }
};

import React, { useState, useRef } from 'react';
import { AppState, MediaItem, MediaType } from '../types';
import { Button } from './ui/Button';
import { 
  Plus, 
  Trash2, 
  Image as ImageIcon, 
  Film, 
  Clock, 
  Link as LinkIcon, 
  X, 
  Code2, 
  Loader2, 
  Upload, 
  FileCheck,
  Globe
} from 'lucide-react';
import { deleteMediaFromCloud, uploadFile } from '../services/storage';

interface MediaLibraryProps {
  state: AppState;
  onUpdate: (newState: AppState) => Promise<void>;
}

export const MediaLibrary: React.FC<MediaLibraryProps> = ({ state, onUpdate }) => {
  const [showAddForm, setShowAddForm] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [uploadMode, setUploadMode] = useState<'link' | 'file'>('file');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [newMedia, setNewMedia] = useState({
    name: '',
    url: '',
    type: 'image' as MediaType,
    duration: 10
  });

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setSelectedFile(file);
      const isVideo = file.type.startsWith('video/');
      setNewMedia(prev => ({
        ...prev,
        name: prev.name || file.name.split('.')[0],
        type: isVideo ? 'video' : 'image'
      }));
    }
  };

  const handleAddMedia = async (e: React.FormEvent) => {
    e.preventDefault();

    if (uploadMode === 'file' && !selectedFile) {
      alert('Por favor, selecione um arquivo.');
      return;
    }
    if (uploadMode === 'link' && !newMedia.url) {
      alert('Por favor, insira a URL.');
      return;
    }

    setIsSaving(true);
    try {
      let finalUrl = newMedia.url;

      if (uploadMode === 'file' && selectedFile && state.syncId) {
        finalUrl = await uploadFile(selectedFile, state.syncId);
      }

      const newItem: MediaItem = {
        id: `m-${Date.now()}`,
        name: newMedia.name || (selectedFile ? selectedFile.name : 'Nova Mídia'),
        url: finalUrl,
        type: newMedia.type,
        duration: newMedia.duration,
        createdAt: Date.now()
      };

      await onUpdate({
        ...state,
        library: [newItem, ...state.library]
      });

      setNewMedia({ name: '', url: '', type: 'image', duration: 10 });
      setSelectedFile(null);
      setShowAddForm(false);
    } catch (err: any) {
      alert('Erro ao salvar mídia: ' + (err.message || 'Verifique se o bucket "media" foi criado no Supabase.'));
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteMedia = async (id: string) => {
    if (confirm('Tem certeza que deseja excluir esta mídia? Ela será removida de todas as playlists.')) {
      try {
        await deleteMediaFromCloud(id);
      } catch (err: any) {
        alert('Erro ao excluir mídia: ' + err.message);
      }
    }
  };

  const getHostnameSafely = (url: string, type: MediaType) => {
    if (type === 'html') return 'Widget/Snippet';
    try {
      const hostname = new URL(url).hostname;
      if (hostname.includes('supabase.co')) return 'Hospedagem AdCast';
      return hostname;
    } catch (e) {
      return 'URL Customizada';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h3 className="text-2xl font-bold text-white">Biblioteca de Mídia</h3>
          <p className="text-slate-400">Gerencie seus arquivos ou utilize links externos para transmissão.</p>
        </div>
        <Button 
          icon={showAddForm ? <X size={18} /> : <Plus size={18} />} 
          variant={showAddForm ? 'secondary' : 'primary'}
          onClick={() => setShowAddForm(!showAddForm)}
        >
          {showAddForm ? 'Cancelar' : 'Adicionar Conteúdo'}
        </Button>
      </div>

      {showAddForm && (
        <div className="bg-slate-900 border border-indigo-500/30 p-6 rounded-2xl animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="flex gap-4 mb-6 p-1 bg-slate-950 rounded-xl w-fit">
            <button 
              onClick={() => setUploadMode('file')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${uploadMode === 'file' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <Upload size={14} /> Upload de Arquivo
            </button>
            <button 
              onClick={() => setUploadMode('link')}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${uploadMode === 'link' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <Globe size={14} /> Link Externo / HTML
            </button>
          </div>

          <form onSubmit={handleAddMedia} className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="text-xs font-semibold text-slate-400 uppercase">Título da Mídia</label>
                <input 
                  type="text" 
                  required
                  disabled={isSaving}
                  value={newMedia.name}
                  onChange={e => setNewMedia({...newMedia, name: e.target.value})}
                  placeholder="Ex: Oferta da Semana"
                  className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none disabled:opacity-50"
                />
              </div>
              <div className="space-y-2">
                <label className="text-xs font-semibold text-slate-400 uppercase">Duração (segundos)</label>
                <input 
                  type="number" 
                  min="1"
                  disabled={isSaving}
                  value={newMedia.duration}
                  onChange={e => setNewMedia({...newMedia, duration: parseInt(e.target.value) || 10})}
                  className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none disabled:opacity-50"
                />
              </div>
            </div>

            {uploadMode === 'file' ? (
              <div 
                onClick={() => fileInputRef.current?.click()}
                className={`border-2 border-dashed rounded-2xl p-8 flex flex-col items-center justify-center gap-3 transition-all cursor-pointer ${selectedFile ? 'border-emerald-500/50 bg-emerald-500/5' : 'border-slate-800 hover:border-indigo-500/50 hover:bg-slate-950'}`}
              >
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  className="hidden" 
                  accept="image/*,video/*"
                  onChange={handleFileChange}
                />
                {selectedFile ? (
                  <>
                    <FileCheck className="text-emerald-500" size={40} />
                    <div className="text-center">
                      <p className="text-emerald-400 font-bold">{selectedFile.name}</p>
                      <p className="text-slate-500 text-xs">{(selectedFile.size / 1024 / 1024).toFixed(2)} MB • Clique para trocar</p>
                    </div>
                  </>
                ) : (
                  <>
                    <div className="p-4 bg-slate-800 rounded-full text-slate-400 group-hover:text-indigo-400 transition-colors">
                      <Upload size={32} />
                    </div>
                    <div className="text-center">
                      <p className="text-slate-300 font-medium">Arraste ou clique para selecionar</p>
                      <p className="text-slate-500 text-xs">Suporta Imagens (PNG, JPG) e Vídeos (MP4)</p>
                    </div>
                  </>
                )}
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-left-2 duration-300">
                <div className="space-y-2">
                  <label className="text-xs font-semibold text-slate-400 uppercase">Tipo de Conteúdo</label>
                  <select 
                    value={newMedia.type}
                    disabled={isSaving}
                    onChange={e => setNewMedia({...newMedia, type: e.target.value as MediaType})}
                    className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-sm text-white outline-none"
                  >
                    <option value="image">Imagem (URL)</option>
                    <option value="video">Vídeo (URL)</option>
                    <option value="html">Widget HTML</option>
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-semibold text-slate-400 uppercase">
                    {newMedia.type === 'html' ? 'Código HTML' : 'Endereço da Mídia (URL)'}
                  </label>
                  {newMedia.type === 'html' ? (
                    <textarea 
                      required
                      rows={4}
                      disabled={isSaving}
                      value={newMedia.url}
                      onChange={e => setNewMedia({...newMedia, url: e.target.value})}
                      className="w-full bg-slate-950 border border-slate-800 rounded-lg px-3 py-2 text-sm text-indigo-300 font-mono outline-none"
                      placeholder="<iframe ...></iframe>"
                    />
                  ) : (
                    <div className="relative">
