                </Button>
                <div className="flex items-center gap-2 justify-center text-slate-500 text-[10px] font-bold uppercase">
                  <Info size={12} />
                  Compatível com Android TV, WebOS e Tizen
                </div>
              </div>
            </div>
          </div>
